function getBonusBossTauntProfile(enemyType) {
  return enemyType ? BONUS_BOSS_TAUNT_PROFILES[enemyType] || null : null;
}

function isBonusBossTauntSpeaker(enemyType) {
  return !!getBonusBossTauntProfile(enemyType);
}

function ensureBonusBossTauntPools() {
  if (!state) return {};
  if (!state.bonusBossTauntPools || typeof state.bonusBossTauntPools !== 'object' || Array.isArray(state.bonusBossTauntPools)) state.bonusBossTauntPools = {};
  return state.bonusBossTauntPools;
}

function resetBonusBossTauntState() {
  if (!state) return;
  state.bonusBossTauntTimer = null;
  state.bonusBossTauntPools = {};
}

function pickBossPoolLine(profile, kind) {
  const pool = Array.isArray(profile?.[kind]) ? profile[kind] : [];
  if (!pool.length || !state) return null;
  const store = ensureBonusBossTauntPools();
  const key = `${profile.id}:${kind}`;
  let remaining = Array.isArray(store[key]) ? store[key].filter(id => pool.some(def => def.id === id)) : [];
  if (!remaining.length) remaining = pool.map(def => def.id);
  const candidates = remaining.map(id => pool.find(def => def.id === id)).filter(Boolean);
  const picked = drawWeightedUltroTaunt(candidates);
  if (!picked) return null;
  store[key] = remaining.filter(id => id !== picked.id);
  return picked;
}

function getBonusBossToastVars(profile) {
  const accent = profile?.accent || '#8fdcff';
  const accent2 = profile?.accent2 || '#385a9e';
  return {
    '--taunt-bg1':'rgba(10,16,26,.95)',
    '--taunt-bg2':'rgba(18,28,40,.96)',
    '--taunt-border':`${accent}88`,
    '--taunt-shadow':`${accent}33`,
    '--taunt-shadow-soft':`${accent}40`,
    '--taunt-kicker':accent,
    '--taunt-avatar-border':`${accent}aa`,
    '--taunt-avatar-glow':`${accent}44`,
    '--taunt-aura1':`${accent}66`,
    '--taunt-aura2':`${accent2}44`
  };
}

function getTauntLineTranslation(def) {
  if (!def) return '';
  return window.UT_I18N ? window.UT_I18N.t(def.ru, def.en) : String(def.ru || '');
}

function showBonusBossTauntToast(profile, def, options = {}) {
  if (!profile || !def || typeof document === 'undefined') return;
  if (networkMode === 'lan' && networkIsHost && state && !options.fromNetwork) {
    const seq = Math.max(0, Math.floor(Number(state.bonusBossTauntEventSeq) || 0)) + 1;
    state.bonusBossTauntEventSeq = seq;
    if (!Array.isArray(state.bonusBossTauntEvents)) state.bonusBossTauntEvents = [];
    state.bonusBossTauntEvents.push({
      seq,
      id: String(def.id || `boss_taunt_${seq}`),
      enemyType: String(profile.id || ''),
      ru: String(def.ru || ''),
      en: String(def.en || def.ru || ''),
      aggressive: !!options.aggressive
    });
    if (state.bonusBossTauntEvents.length > 10) state.bonusBossTauntEvents.splice(0, state.bonusBossTauntEvents.length - 10);
  }
  let stack = document.querySelector('.ultro-taunt-stack');
  if (!stack) {
    stack = document.createElement('div');
    stack.className = 'ultro-taunt-stack';
    document.body.appendChild(stack);
  }
  while (stack.children.length >= 2) stack.removeChild(stack.firstElementChild);
  const toast = document.createElement('div');
  toast.className = 'ultro-taunt bonus-boss-taunt';
  const cssVars = getBonusBossToastVars(profile);
  for (const [key, value] of Object.entries(cssVars)) toast.style.setProperty(key, value);
  const avatar = document.createElement('div');
  avatar.className = 'ultro-taunt-avatar';
  const img = document.createElement('img');
  img.src = profile.avatar;
  img.alt = profile.speakerRu || 'BOSS';
  img.loading = 'lazy';
  avatar.appendChild(img);
  const copy = document.createElement('div');
  const kicker = document.createElement('b');
  kicker.textContent = window.UT_I18N ? window.UT_I18N.t(profile.speakerRu || 'БОСС', profile.speakerEn || 'BOSS') : (profile.speakerRu || 'БОСС');
  const title = document.createElement('strong');
  title.textContent = getTauntLineTranslation(def);
  copy.append(kicker, title);
  toast.append(avatar, copy);
  stack.appendChild(toast);
  playUltroMessagePing();
  scheduleUltroAvatarLife(avatar, toast, { aggressive: !!options.aggressive, corrupted: false });
  setTimeout(() => toast.classList.add('out'), 7600);
  setTimeout(() => toast.remove(), 7950);
}

function getActiveBonusBossSpeakers() {
  if (!state?.inBonusLevel || isUltroBonusLevelKey(state?.bonusLevelKey)) return [];
  return (state.enemies || []).filter(enemy => enemy?.alive && isBonusBossTauntSpeaker(enemy.enemyType));
}

function shouldRunBonusBossTaunts() {
  if (!gameStarted || !state || state.paused || state.gameOver) return false;
  if (networkMode === 'lan' && !networkIsHost) return false;
  if (!state.inBonusLevel || isUltroBonusLevelKey(state.bonusLevelKey)) return false;
  if (Number(state.levelTransition || 0) > 0 || Number(state.roundTransition || 0) > 0) return false;
  return getActiveBonusBossSpeakers().length > 0;
}

function updateBonusBossTaunts(dt) {
  if (!shouldRunBonusBossTaunts()) {
    if (state) state.bonusBossTauntTimer = null;
    return;
  }
  if (!Number.isFinite(Number(state.bonusBossTauntTimer))) state.bonusBossTauntTimer = 9.5 + Math.random() * 5.5;
  state.bonusBossTauntTimer -= dt;
  if (state.bonusBossTauntTimer > 0) return;
  const speakers = getActiveBonusBossSpeakers();
  const speaker = choose(speakers);
  const profile = getBonusBossTauntProfile(speaker?.enemyType);
  const picked = profile ? pickBossPoolLine(profile, 'random') : null;
  if (profile && picked) showBonusBossTauntToast(profile, picked);
  state.bonusBossTauntTimer = 12 + Math.random() * 8;
}

function updateBonusBossPhaseTaunts(t) {
  if (!t?.alive || !isBonusBossTauntSpeaker(t.enemyType)) return;
  if (networkMode === 'lan' && !networkIsHost) return;
  const profile = getBonusBossTauntProfile(t.enemyType);
  if (!profile) return;
  const currentPhase = getBossCurrentPhase(t);
  const previousPhase = Number.isFinite(Number(t.bonusBossLastAnnouncedPhase)) ? Number(t.bonusBossLastAnnouncedPhase) : 1;
  if (currentPhase <= previousPhase) {
    t.bonusBossLastAnnouncedPhase = currentPhase;
    return;
  }
  for (let phase = previousPhase + 1; phase <= currentPhase; phase++) {
    const def = profile.phase?.[String(phase)] || profile.phase?.[phase];
    if (!def) continue;
    const delay = (phase - (previousPhase + 1)) * 850;
    if (delay <= 0) showBonusBossTauntToast(profile, def, { aggressive: true });
    else setTimeout(() => {
      if (t?.alive && state?.inBonusLevel && !state?.gameOver) showBonusBossTauntToast(profile, def, { aggressive: true });
    }, delay);
  }
  t.bonusBossLastAnnouncedPhase = currentPhase;
  state.bonusBossTauntTimer = Math.max(Number(state.bonusBossTauntTimer) || 0, 8 + Math.random() * 4);
}

function showBonusBossPlayerDeathTaunt() {
  const speakers = getActiveBonusBossSpeakers();
  if (!speakers.length || state?.gameOver) return;
  const speaker = choose(speakers);
  const profile = getBonusBossTauntProfile(speaker?.enemyType);
  const def = profile ? pickBossPoolLine(profile, 'death') : null;
  if (profile && def) showBonusBossTauntToast(profile, def, { aggressive: true });
  state.bonusBossTauntTimer = Math.max(Number(state?.bonusBossTauntTimer) || 0, 10 + Math.random() * 4);
}
