  function combatSfxLocalObjectId(obj,prefix='p'){
    if(!obj)return `${prefix}:none`;
    if(obj._nid!=null)return `${prefix}:n${obj._nid}`;
    if(obj.networkId!=null)return `${prefix}:net${obj.networkId}`;
    if(obj._sfxAudioId==null){try{obj._sfxAudioId=combatSfxLocalId++;}catch(_){return `${prefix}:tmp${combatSfxLocalId++}`;}}
    return `${prefix}:l${obj._sfxAudioId}`;
  }
  function combatSfxTankId(t){
    if(!t)return 'tank:none';
    if(t._nid!=null)return `tank:n${t._nid}`;
    if(t.team==='player'&&t.playerSlot)return `tank:p${t.playerSlot}`;
    if(t._sfxEntityId==null){try{t._sfxEntityId=combatSfxEntityId++;}catch(_){return `tank:t${combatSfxEntityId++}`;}}
    return `tank:l${t._sfxEntityId}`;
  }
  function combatSfxTankType(t){return String(t?.enemyType||t?.playerType||'tank');}
