    const g1=ctx.createGain(),g2=ctx.createGain();g1.gain.value=.18;g2.gain.value=.095;o1.connect(f1);f1.connect(g1);o2.connect(g2);g1.connect(gain);g2.connect(gain);
    const noise=ctx.createBufferSource(),nf=ctx.createBiquadFilter(),ng=ctx.createGain();noise.buffer=combatSfxNoise(ctx);noise.loop=true;nf.type=family==='void'?'bandpass':'highpass';nf.frequency.value=family==='void'?420:(family==='sand'?720:2200);nf.Q.value=family==='electric'?3:1.2;ng.gain.value=family==='sand'?.09:.045;noise.connect(nf);nf.connect(ng);ng.connect(gain);
    o1.start(now);o2.start(now);noise.start(now);
