    const roar=ctx.createBufferSource(),rf=ctx.createBiquadFilter(),rg=ctx.createGain();roar.buffer=combatSfxNoise(ctx);roar.loop=true;rf.type='lowpass';rf.frequency.value=430;rf.Q.value=.45;rg.gain.value=.18;roar.connect(rf);rf.connect(rg);rg.connect(gain);
    const motor=ctx.createOscillator(),mg=ctx.createGain();motor.type='sawtooth';motor.frequency.value=76;mg.gain.value=.055;motor.connect(mg);mg.connect(gain);
