      for(const field of COMBAT_SFX_CHARGE_FIELDS){const v=Math.max(0,Number(t[field]||0)),pv=Math.max(0,Number(prev[field]||0));next[field]=v;if(v>0&&pv<=0){const fam=combatSfxFamilyForTank(t,field),desc={id:`${type}:${field}:charge`,family:fam,strength:1.05,token:field,source:type};playCombatWeaponSfx(desc,'fire',t.x+t.w/2,t.y+t.h/2);}}
      for(const field of COMBAT_SFX_ATTACK_ACTIVE_FIELDS){const v=Math.max(0,Number(t[field]||0)),pv=Math.max(0,Number(prev[field]||0));next[field]=v;if(v>0&&pv<=0){const fam=combatSfxFamilyForTank(t,field),desc={id:`${type}:${field}:active`,family:fam,strength:1.35,token:field,source:type};playCombatWeaponSfx(desc,'fire',t.x+t.w/2,t.y+t.h/2);}}
      for(const field of COMBAT_SFX_ATTACK_TIMER_FIELDS){const raw=Number(t[field]),old=Number(prev[field]);next[field]=Number.isFinite(raw)?raw:null;if(Number.isFinite(raw)&&Number.isFinite(old)&&raw>old+.7){const fam=combatSfxFamilyForTank(t,field),desc={id:`${type}:${field}:pulse`,family:fam,strength:1.25,token:field,source:type};playCombatWeaponSfx(desc,'fire',t.x+t.w/2,t.y+t.h/2);}}
      for(const field of COMBAT_SFX_LASER_FIELDS){const v=Math.max(0,Number(t[field]||0));next[field]=v;if(v>0){const key=`${id}:${field}`,loop=startCombatLaserLoop(key,combatSfxFamilyForTank(t,field),t.x+t.w/2);activeLoops.add(key);if(loop){loop.lastSeen=performance.now();if(loop.pan)loop.pan.pan.setTargetAtTime(clamp(((t.x+t.w/2)/(W||1)-.5)*1.45,-.82,.82),loop.ctx.currentTime,.035);}}}
