  function applyAudioSettings() {
    if (menuMusicCtx && menuMusicMaster) {
      const now = menuMusicCtx.currentTime;
      menuMusicMaster.gain.cancelScheduledValues(now);
      menuMusicMaster.gain.setTargetAtTime(musicVolumeSetting, now, .025);
    }
    if (menuMusicCtx && menuSfxMaster) {
      const now = menuMusicCtx.currentTime;
      menuSfxMaster.gain.cancelScheduledValues(now);
      menuSfxMaster.gain.setTargetAtTime(effectsVolumeSetting, now, .025);
    }
    if (ultroBossMusicAudio && !ultroBossMusicFading) {
      ultroBossMusicAudio.volume = getUltroBossMusicVolume();
    }
    refreshAudioSettingsUi();
  }

  function setMusicVolume(value) {
    musicVolumeSetting = clampAudioSetting(value, AUDIO_DEFAULT_MUSIC);
    saveAudioSettings();
    applyAudioSettings();
  }

  function setEffectsVolume(value) {
    effectsVolumeSetting = clampAudioSetting(value, AUDIO_DEFAULT_EFFECTS);
    saveAudioSettings();
    applyAudioSettings();
  }

  function menuMusicTone(ctx, at, duration, frequency, gainValue, type = 'sine', detune = 0, destination = menuMusicBus) {
    if (!ctx || !destination || !Number.isFinite(frequency) || frequency <= 0) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, at);
    osc.detune.setValueAtTime(detune, at);
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(type === 'sine' ? 1450 : 920, at);
    filter.Q.value = .75;
    const attack = Math.min(.12, duration * .16);
    const release = Math.min(.7, duration * .35);
    gain.gain.setValueAtTime(.0001, at);
    gain.gain.exponentialRampToValueAtTime(Math.max(.0002, gainValue), at + attack);
    gain.gain.setValueAtTime(Math.max(.0002, gainValue * .86), Math.max(at + attack, at + duration - release));
    gain.gain.exponentialRampToValueAtTime(.0001, at + duration);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(destination);
    osc.start(at);
    osc.stop(at + duration + .04);
  }

  function menuMusicNoiseHit(ctx, at, strength = .12, low = 70, high = 180, duration = .28) {
    if (!ctx || !menuMusicBus) return;
    const length = Math.max(64, Math.floor(ctx.sampleRate * duration));
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) {
      const env = Math.pow(1 - i / length, 2.4);
      data[i] = (Math.random() * 2 - 1) * env;
    }
    const source = ctx.createBufferSource();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    source.buffer = buffer;
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime((low + high) * .5, at);
    filter.Q.value = 1.0;
    gain.gain.setValueAtTime(Math.max(.001, strength), at);
    gain.gain.exponentialRampToValueAtTime(.0001, at + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(menuMusicBus);
    source.start(at);
    source.stop(at + duration + .03);
  }

  function menuMusicKick(ctx, at, strength = .23) {
    if (!ctx || !menuMusicBus) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(112, at);
    osc.frequency.exponentialRampToValueAtTime(42, at + .20);
    gain.gain.setValueAtTime(Math.max(.001, strength), at);
    gain.gain.exponentialRampToValueAtTime(.0001, at + .28);
    osc.connect(gain);
    gain.connect(menuMusicBus);
    osc.start(at);
    osc.stop(at + .30);
  }

  function menuMusicRiser(ctx, at, duration = 2.4, strength = .035) {
    if (!ctx || !menuMusicBus) return;
    const length = Math.max(64, Math.floor(ctx.sampleRate * duration));
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) {
      const t = i / length;
      data[i] = (Math.random() * 2 - 1) * Math.pow(t, 1.7) * (1 - t * .25);
    }
    const source = ctx.createBufferSource();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    source.buffer = buffer;
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(220, at);
    filter.frequency.exponentialRampToValueAtTime(1900, at + duration);
    filter.Q.value = .75;
    gain.gain.setValueAtTime(.0001, at);
    gain.gain.exponentialRampToValueAtTime(Math.max(.001, strength), at + duration * .82);
    gain.gain.exponentialRampToValueAtTime(.0001, at + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(menuMusicBus);
    source.start(at);
    source.stop(at + duration + .03);
  }

  function scheduleMenuMusicCycle(ctx, startAt) {
    if (!ctx || !menuMusicBus) return;
    // D minor / cinematic military progression: Dm – Bb – C – Dm – Gm – Bb – C – Dm.
    const roots = [73.416,58.270,65.406,73.416,49.000,58.270,65.406,73.416];
    const chordTypes = [0,1,1,0,0,1,1,0]; // 0 minor, 1 major
    for (let bar = 0; bar < MENU_MUSIC_CYCLE_BARS; bar++) {
      const barAt = startAt + bar * MENU_MUSIC_BAR;
      const root = roots[bar];
      const third = root * Math.pow(2, (chordTypes[bar] ? 4 : 3) / 12);
      const fifth = root * Math.pow(2, 7 / 12);
      // Deep mechanical drone and low strings.
      menuMusicTone(ctx, barAt, MENU_MUSIC_BAR * .98, root / 2, .052, 'sine');
      menuMusicTone(ctx, barAt, MENU_MUSIC_BAR * .98, root, .020, 'sawtooth', -5);
      menuMusicTone(ctx, barAt, MENU_MUSIC_BAR * .98, fifth, .013, 'triangle', 4);
      // Slow brass-like chord swells.
      menuMusicTone(ctx, barAt + MENU_MUSIC_BEAT * .10, MENU_MUSIC_BAR * .83, root * 2, .0105, 'sawtooth', -8);
      menuMusicTone(ctx, barAt + MENU_MUSIC_BEAT * .12, MENU_MUSIC_BAR * .82, third * 2, .0080, 'triangle', 5);
      menuMusicTone(ctx, barAt + MENU_MUSIC_BEAT * .14, MENU_MUSIC_BAR * .80, fifth * 2, .0075, 'sawtooth', 9);
      // March pulse: heavier first/third beats and quieter secondary hits.
      for (let beat = 0; beat < 4; beat++) {
        const beatAt = barAt + beat * MENU_MUSIC_BEAT;
        menuMusicKick(ctx, beatAt, beat % 2 === 0 ? .145 : .080);
        if (beat === 0 || beat === 2) menuMusicNoiseHit(ctx, beatAt + .018, beat === 0 ? .060 : .045, 70, 260, .22);
      }
      // Sparse upper motif, increasingly present toward the cycle ending.
      if (bar === 1 || bar === 3 || bar === 5 || bar === 7) {
        const motifRoot = root * 4;
        const motif = bar === 7 ? [0,3,7,12] : [0,7,3,7];
        for (let i = 0; i < motif.length; i++) {
          const noteAt = barAt + MENU_MUSIC_BEAT * (i + .15);
          const freq = motifRoot * Math.pow(2, motif[i] / 12);
          menuMusicTone(ctx, noteAt, MENU_MUSIC_BEAT * .62, freq, bar === 7 ? .010 : .0065, 'triangle');
        }
      }
    }
    menuMusicRiser(ctx, startAt + MENU_MUSIC_CYCLE - MENU_MUSIC_BAR * .78, MENU_MUSIC_BAR * .75, .020);
  }

  function scheduleNextMenuMusicCycles(generation) {
    if (!menuMusicRunning || generation !== menuMusicGeneration || !menuMusicCtx) return;
    const ctx = menuMusicCtx;
    while (menuMusicCycleStart < ctx.currentTime + MENU_MUSIC_CYCLE * 1.35) {
      scheduleMenuMusicCycle(ctx, menuMusicCycleStart);
      menuMusicCycleStart += MENU_MUSIC_CYCLE;
    }
    clearTimeout(menuMusicTimer);
    menuMusicTimer = setTimeout(() => scheduleNextMenuMusicCycles(generation), Math.max(1000, MENU_MUSIC_CYCLE * 500));
  }

  async function startMenuMusic() {
    if (gameStarted) return;
    const ctx = getMenuMusicContext();
    if (!ctx || !menuMusicMaster) return;
    try { if (ctx.state === 'suspended') await ctx.resume(); } catch (_) {}
    if (ctx.state !== 'running') return;
    if (menuMusicRunning) return;
    menuMusicRunning = true;
    menuMusicGeneration++;
    const generation = menuMusicGeneration;
    const now = ctx.currentTime;
    const bus = ctx.createGain();
    bus.gain.setValueAtTime(.0001, now);
    bus.gain.exponentialRampToValueAtTime(.24, now + 1.8);
    bus.connect(menuMusicMaster);
    menuMusicBus = bus;
    menuMusicCycleStart = now + .08;
    scheduleNextMenuMusicCycles(generation);
  }

  function stopMenuMusic(fadeSeconds = 1.25) {
    menuMusicRunning = false;
    menuMusicGeneration++;
    clearTimeout(menuMusicTimer);
    menuMusicTimer = null;
    if (!menuMusicCtx || !menuMusicBus) return;
    const bus = menuMusicBus;
    menuMusicBus = null;
    const now = menuMusicCtx.currentTime;
    const fade = Math.max(.08, Number(fadeSeconds) || 1.25);
    bus.gain.cancelScheduledValues(now);
    bus.gain.setValueAtTime(Math.max(.0001, Number(bus.gain.value) || .0001), now);
    bus.gain.exponentialRampToValueAtTime(.0001, now + fade);
    setTimeout(() => { try { bus.disconnect(); } catch (_) {} }, (fade + .15) * 1000);
  }

  function primeMenuMusicFromGesture() {
    if (gameStarted) return;
    startMenuMusic();
  }

  function schedulePortalSpawnSound(ctx, secret = false) {
    if (!ctx || !menuSfxMaster) return;
    const now = ctx.currentTime + .018;
    const bus = ctx.createGain();
    bus.gain.setValueAtTime(.0001, now);
    bus.gain.exponentialRampToValueAtTime(secret ? .46 : .38, now + .035);
    bus.gain.exponentialRampToValueAtTime(.0001, now + (secret ? 2.35 : 1.85));
    bus.connect(menuSfxMaster);

    // Low dimensional surge: the secret ULTRO rift is deeper and slightly unstable.
    const low = ctx.createOscillator();
    const lowGain = ctx.createGain();
    const lowFilter = ctx.createBiquadFilter();
    low.type = secret ? 'sawtooth' : 'triangle';
    low.frequency.setValueAtTime(secret ? 44 : 58, now);
    low.frequency.exponentialRampToValueAtTime(secret ? 86 : 112, now + .52);
    low.frequency.exponentialRampToValueAtTime(secret ? 38 : 48, now + (secret ? 2.05 : 1.55));
    lowFilter.type = 'lowpass';
    lowFilter.frequency.setValueAtTime(secret ? 460 : 640, now);
    lowFilter.frequency.exponentialRampToValueAtTime(secret ? 980 : 1320, now + .48);
    lowFilter.frequency.exponentialRampToValueAtTime(secret ? 360 : 520, now + (secret ? 2.0 : 1.5));
    lowFilter.Q.value = secret ? 1.2 : .8;
    lowGain.gain.setValueAtTime(.0001, now);
    lowGain.gain.exponentialRampToValueAtTime(secret ? .19 : .15, now + .08);
    lowGain.gain.exponentialRampToValueAtTime(.0001, now + (secret ? 2.18 : 1.72));
    low.connect(lowFilter); lowFilter.connect(lowGain); lowGain.connect(bus);
    low.start(now); low.stop(now + (secret ? 2.22 : 1.76));

    // Air tearing open: filtered noise sweeping upward, then collapsing.
    const noiseDuration = secret ? 2.1 : 1.55;
    const noiseLength = Math.max(64, Math.floor(ctx.sampleRate * noiseDuration));
    const noiseBuffer = ctx.createBuffer(1, noiseLength, ctx.sampleRate);
    const noiseData = noiseBuffer.getChannelData(0);
    for (let i = 0; i < noiseLength; i++) {
      const t = i / noiseLength;
      const rise = Math.min(1, t / .22);
      const tail = Math.pow(1 - t, secret ? 1.15 : 1.55);
      noiseData[i] = (Math.random() * 2 - 1) * rise * tail;
    }
    const noise = ctx.createBufferSource();
    const noiseFilter = ctx.createBiquadFilter();
    const noiseGain = ctx.createGain();
    noise.buffer = noiseBuffer;
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(secret ? 240 : 360, now);
    noiseFilter.frequency.exponentialRampToValueAtTime(secret ? 3100 : 2600, now + .42);
    noiseFilter.frequency.exponentialRampToValueAtTime(secret ? 720 : 980, now + noiseDuration);
    noiseFilter.Q.value = secret ? .82 : .65;
    noiseGain.gain.setValueAtTime(.0001, now);
    noiseGain.gain.exponentialRampToValueAtTime(secret ? .18 : .14, now + .16);
    noiseGain.gain.exponentialRampToValueAtTime(.0001, now + noiseDuration);
    noise.connect(noiseFilter); noiseFilter.connect(noiseGain); noiseGain.connect(bus);
    noise.start(now); noise.stop(now + noiseDuration + .02);

    // Bright portal ignition chime. Secret rifts use a tritone-like, colder interval.
    const portalNotes = secret ? [184.997, 261.626, 369.994, 554.365] : [220.000, 329.628, 440.000, 659.255];
    portalNotes.forEach((freq, index) => {
      const at = now + .18 + index * (secret ? .082 : .072);
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const filter = ctx.createBiquadFilter();
      osc.type = index % 2 ? 'triangle' : 'sine';
      osc.frequency.setValueAtTime(freq, at);
      if (secret) osc.detune.setValueAtTime(index % 2 ? -12 : 8, at);
      filter.type = 'bandpass'; filter.frequency.setValueAtTime(Math.min(4200, freq * 4.2), at); filter.Q.value = 1.1;
      gain.gain.setValueAtTime(.0001, at);
      gain.gain.exponentialRampToValueAtTime((secret ? .075 : .066) * (1 - index * .10), at + .018);
      gain.gain.exponentialRampToValueAtTime(.0001, at + (secret ? .82 : .62));
      osc.connect(filter); filter.connect(gain); gain.connect(bus);
      osc.start(at); osc.stop(at + (secret ? .86 : .66));
    });

    // Secret portal gets two tiny dimensional glitches after ignition.
    if (secret) {
      [0.62, 1.02].forEach((offset, idx) => {
        const at = now + offset;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(idx ? 176 : 233, at);
        osc.frequency.exponentialRampToValueAtTime(idx ? 92 : 118, at + .105);
        gain.gain.setValueAtTime(.0001, at);
        gain.gain.exponentialRampToValueAtTime(.028, at + .008);
        gain.gain.exponentialRampToValueAtTime(.0001, at + .12);
        osc.connect(gain); gain.connect(bus); osc.start(at); osc.stop(at + .13);
      });
    }

    setTimeout(() => { try { bus.disconnect(); } catch (_) {} }, (secret ? 2.55 : 2.05) * 1000);
  }

  function playBonusPortalSpawnSound(secret = false) {
    const ctx = getMenuMusicContext();
    if (!ctx || !menuSfxMaster) return;
    const play = () => {
      if (ctx.state !== 'running') return;
      schedulePortalSpawnSound(ctx, !!secret);
    };
    if (ctx.state === 'suspended') {
      try { ctx.resume().then(play).catch(() => {}); } catch (_) {}
    } else play();
  }

