  function getBattleMusicDistortionCurve() {
    if (battleMusicDistortionCurve) return battleMusicDistortionCurve;
    const samples = 512;
    const curve = new Float32Array(samples);
    const drive = 34;
    for (let i = 0; i < samples; i++) {
      const x = i * 2 / (samples - 1) - 1;
      curve[i] = ((3 + drive) * x * 18 * Math.PI / 180) / (Math.PI + drive * Math.abs(x));
    }
    battleMusicDistortionCurve = curve;
    return curve;
  }

  function battleMusicTone(ctx, destination, at, duration, frequency, gainValue, type='sine', options={}) {
    if (!ctx || !destination || !Number.isFinite(frequency) || frequency <= 0) return;
    const osc = ctx.createOscillator();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, at);
    osc.detune.setValueAtTime(Number(options.detune)||0, at);
    filter.type = options.filterType || 'lowpass';
    filter.frequency.setValueAtTime(Math.max(80, Number(options.cutoff) || (options.drive ? 1150 : 1700)), at);
    filter.Q.value = Math.max(.1, Number(options.q) || .8);
    const attack = Math.max(.004, Math.min(Number(options.attack)||.035, duration*.22));
    const release = Math.max(.025, Math.min(Number(options.release)||.20, duration*.44));
    gain.gain.setValueAtTime(.0001, at);
    gain.gain.exponentialRampToValueAtTime(Math.max(.0002,gainValue), at+attack);
    gain.gain.setValueAtTime(Math.max(.0002,gainValue*.82), Math.max(at+attack,at+duration-release));
    gain.gain.exponentialRampToValueAtTime(.0001, at+duration);
    osc.connect(filter);
    if (options.drive) {
      const shaper = ctx.createWaveShaper();
      shaper.curve = getBattleMusicDistortionCurve();
      shaper.oversample = '2x';
      filter.connect(shaper); shaper.connect(gain);
    } else filter.connect(gain);
    gain.connect(destination);
    osc.start(at); osc.stop(at+duration+.04);
  }

  function battleMusicNoise(ctx, destination, at, duration=.18, gainValue=.05, filterType='bandpass', frequency=1200, q=.8) {
    if (!ctx || !destination) return;
    const length = Math.max(64, Math.floor(ctx.sampleRate*duration));
    const buffer = ctx.createBuffer(1,length,ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i=0;i<length;i++) {
      const t=i/length;
      data[i]=(Math.random()*2-1)*Math.pow(1-t,2.1);
    }
    const source=ctx.createBufferSource();
    const filter=ctx.createBiquadFilter();
    const gain=ctx.createGain();
    source.buffer=buffer;
    filter.type=filterType; filter.frequency.setValueAtTime(frequency,at); filter.Q.value=q;
    gain.gain.setValueAtTime(Math.max(.0002,gainValue),at);
    gain.gain.exponentialRampToValueAtTime(.0001,at+duration);
    source.connect(filter); filter.connect(gain); gain.connect(destination);
    source.start(at); source.stop(at+duration+.03);
  }

  function battleMusicKick(ctx,destination,at,strength=.18) {
    const osc=ctx.createOscillator(), gain=ctx.createGain();
    osc.type='sine'; osc.frequency.setValueAtTime(145,at); osc.frequency.exponentialRampToValueAtTime(43,at+.18);
    gain.gain.setValueAtTime(Math.max(.001,strength),at); gain.gain.exponentialRampToValueAtTime(.0001,at+.25);
    osc.connect(gain); gain.connect(destination); osc.start(at); osc.stop(at+.27);
  }

  function battleMusicSnare(ctx,destination,at,strength=.07) {
    battleMusicNoise(ctx,destination,at,.19,strength,'bandpass',1450,.72);
    battleMusicTone(ctx,destination,at,.12,174,strength*.38,'triangle',{cutoff:900,attack:.004,release:.10});
  }

  function battleMusicRiser(ctx,destination,at,duration=1.6,strength=.026) {
    if (!ctx || !destination) return;
    const length=Math.max(64,Math.floor(ctx.sampleRate*duration));
    const buffer=ctx.createBuffer(1,length,ctx.sampleRate), data=buffer.getChannelData(0);
    for(let i=0;i<length;i++){const t=i/length;data[i]=(Math.random()*2-1)*Math.pow(t,1.45)*(1-t*.18);}
    const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();
    source.buffer=buffer; filter.type='bandpass'; filter.frequency.setValueAtTime(180,at); filter.frequency.exponentialRampToValueAtTime(2600,at+duration); filter.Q.value=.7;
    gain.gain.setValueAtTime(.0001,at); gain.gain.exponentialRampToValueAtTime(strength,at+duration*.78); gain.gain.exponentialRampToValueAtTime(.0001,at+duration);
    source.connect(filter);filter.connect(gain);gain.connect(destination);source.start(at);source.stop(at+duration+.03);
  }

  function campaignMusicSupersaw(ctx,destination,at,duration,frequency,gainValue,cutoff=1850,spread=11) {
    if(!ctx||!destination||!Number.isFinite(frequency)||frequency<=0)return;
    const filter=ctx.createBiquadFilter(), gain=ctx.createGain();
    filter.type='lowpass';filter.frequency.setValueAtTime(Math.max(320,cutoff),at);filter.Q.value=.82;
    const attack=Math.min(.11,duration*.15),release=Math.min(.32,duration*.32);
    gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,gainValue),at+attack);
    gain.gain.setValueAtTime(Math.max(.0002,gainValue*.72),Math.max(at+attack,at+duration-release));gain.gain.exponentialRampToValueAtTime(.0001,at+duration);
    for(const detune of [-spread,0,spread]){
      const osc=ctx.createOscillator();osc.type='sawtooth';osc.frequency.setValueAtTime(frequency,at);osc.detune.setValueAtTime(detune,at);
      osc.connect(filter);osc.start(at);osc.stop(at+duration+.04);
    }
    filter.connect(gain);gain.connect(destination);
  }

  function campaignMusicWobble(ctx,destination,at,duration,frequency,gainValue=.034,rate=4,peakCutoff=1450) {
    if(!ctx||!destination||!Number.isFinite(frequency)||frequency<=0)return;
    const filter=ctx.createBiquadFilter(),shaper=ctx.createWaveShaper(),gain=ctx.createGain();
    filter.type='lowpass';filter.Q.value=2.8;filter.frequency.setValueAtTime(150,at);
    shaper.curve=getBattleMusicDistortionCurve();shaper.oversample='2x';
    const osc=ctx.createOscillator(),sub=ctx.createOscillator(),subGain=ctx.createGain();
    osc.type='sawtooth';osc.frequency.setValueAtTime(frequency,at);osc.detune.setValueAtTime(-5,at);
    sub.type='sine';sub.frequency.setValueAtTime(frequency/2,at);subGain.gain.value=.34;
    const slices=Math.max(2,Math.round(duration/(60/132)*(rate/2)));
    for(let i=0;i<slices;i++){
      const t0=at+duration*i/slices,t1=at+duration*(i+.48)/slices,t2=at+duration*(i+1)/slices;
      const peak=Math.max(420,peakCutoff*(.72+.28*Math.sin((i+1)*1.77)**2));
      filter.frequency.setValueAtTime(160,t0);filter.frequency.exponentialRampToValueAtTime(peak,t1);filter.frequency.exponentialRampToValueAtTime(180,t2);
    }
    gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(gainValue,at+.012);gain.gain.setValueAtTime(gainValue*.82,Math.max(at+.02,at+duration-.08));gain.gain.exponentialRampToValueAtTime(.0001,at+duration);
    osc.connect(filter);sub.connect(subGain);subGain.connect(filter);filter.connect(shaper);shaper.connect(gain);gain.connect(destination);
    osc.start(at);sub.start(at);osc.stop(at+duration+.04);sub.stop(at+duration+.04);
  }

  function campaignMusicHat(ctx,destination,at,strength=.010,open=false){
    battleMusicNoise(ctx,destination,at,open?.105:.038,strength,'highpass',open?6100:7600,.30);
  }

  function campaignMusicClap(ctx,destination,at,strength=.052){
    battleMusicNoise(ctx,destination,at,.12,strength,'bandpass',1750,.55);
    battleMusicNoise(ctx,destination,at+.018,.095,strength*.72,'highpass',3100,.42);
    battleMusicNoise(ctx,destination,at+.037,.080,strength*.48,'bandpass',1250,.60);
  }

  function scheduleCampaignCalmCycle(ctx,destination,startAt,config,style) {
    // Despite the historic function name, this is the modern 52-level campaign mix.
    // It deliberately avoids the old sparse 8-bit-like triangle melody.
    const beat=60/config.bpm,bar=beat*4;
    const profiles={
      campaignGreen:{bass:[0,0,7,0,3,0,7,10],lead:[12,7,10,7,15,12,10,7],cutoff:1850,wobble:4,pad:.0085,hat:.0095,drop:[2,6]},
      campaignWater:{bass:[0,null,7,5,0,10,7,null],lead:[12,10,7,5,14,12,10,7],cutoff:2350,wobble:3,pad:.0092,hat:.0084,drop:[3,7]},
      campaignDesert:{bass:[0,1,0,7,5,1,10,7],lead:[12,13,17,19,17,13,12,10],cutoff:1650,wobble:4,pad:.0080,hat:.0105,drop:[1,5]},
      campaignSteel:{bass:[0,0,6,0,1,0,7,6],lead:[12,6,13,7,18,13,7,6],cutoff:1350,wobble:6,pad:.0068,hat:.0122,drop:[0,4],industrial:true},
      campaignNight:{bass:[0,null,6,3,0,10,7,6],lead:[12,15,10,7,18,15,12,10],cutoff:2050,wobble:5,pad:.0078,hat:.0100,drop:[2,6],dark:true},
      campaignBoss:{bass:[0,0,1,6,0,7,6,1],lead:[12,13,18,19,13,12,7,6],cutoff:1580,wobble:7,pad:.0072,hat:.0130,drop:[0,2,4,6],industrial:true,boss:true}
    };
    const profile=profiles[style]||profiles.campaignGreen;
    for(let b=0;b<config.bars;b++){
      const at=startAt+b*bar,root=config.roots[b%config.roots.length];
      const minor=root*Math.pow(2,3/12),fifth=root*Math.pow(2,7/12);

      // Wide modern pad and deep sub foundation.
      campaignMusicSupersaw(ctx,destination,at+.012,bar*.96,root*2,profile.pad,profile.cutoff*.72,10);
      campaignMusicSupersaw(ctx,destination,at+.035,bar*.92,minor*2,profile.pad*.56,profile.cutoff*.84,13);
      battleMusicTone(ctx,destination,at,bar*.98,root/2,.030,'sine',{cutoff:330,attack:.035,release:.24});
      if(b%2===0) campaignMusicSupersaw(ctx,destination,at+.08,bar*1.76,fifth*2,profile.pad*.40,profile.cutoff,16);

      // Bass-drop pattern: short filtered growls/wobbles rather than chip-style notes.
      for(let step=0;step<8;step++){
        const semi=profile.bass[(step+b)%profile.bass.length];
        if(semi===null||semi===undefined)continue;
        const noteAt=at+step*(beat/2),freq=root*Math.pow(2,semi/12);
        const accent=(step===0||profile.drop.includes(step));
        campaignMusicWobble(ctx,destination,noteAt,beat*(accent?.47:.38),freq,accent?(profile.boss?.048:.041):.031,profile.wobble,profile.cutoff*(accent?1.05:.86));
      }

      // Punchy contemporary drum programming.
      if(profile.boss||profile.industrial){
        battleMusicKick(ctx,destination,at,.19);battleMusicKick(ctx,destination,at+beat*.50,.088);
        battleMusicKick(ctx,destination,at+beat*2,.160);if(profile.boss)battleMusicKick(ctx,destination,at+beat*2.50,.102);
        campaignMusicClap(ctx,destination,at+beat*2,.064);
      }else{
        battleMusicKick(ctx,destination,at,.17);battleMusicKick(ctx,destination,at+beat*1.5,.092);battleMusicKick(ctx,destination,at+beat*2.75,.125);
        campaignMusicClap(ctx,destination,at+beat,.047);campaignMusicClap(ctx,destination,at+beat*3,.052);
      }
      for(let h=0;h<8;h++)campaignMusicHat(ctx,destination,at+h*(beat/2),profile.hat*(h%2?1:.72),h===7||h===3);
      if(profile.industrial)for(let h=1;h<8;h+=2)campaignMusicHat(ctx,destination,at+h*(beat/2)+beat*.25,profile.hat*.58,false);

      // Filtered synth stabs / arpeggio. Kept sparse and wide so it reads as electro, not 8-bit.
      if(b%2===1||profile.boss){
        for(let i=0;i<4;i++){
          const semi=profile.lead[(i+b*2)%profile.lead.length],noteAt=at+beat*(.25+i*.92);
          const freq=root*4*Math.pow(2,semi/12);
          campaignMusicSupersaw(ctx,destination,noteAt,beat*(profile.dark?.42:.31),freq,profile.boss?.0078:.0057,profile.cutoff*1.42,18);
        }
      }

      // Modern build-ups at section boundaries.
      if(b===3||b===7){
        battleMusicRiser(ctx,destination,at+bar*.42,bar*.56,profile.boss?.036:.026);
        for(let r=0;r<6;r++)campaignMusicClap(ctx,destination,at+bar*.72+r*(bar*.28/6),.020+r*.0045);
        battleMusicNoise(ctx,destination,at+bar*.965,.22,profile.boss?.055:.036,'bandpass',profile.industrial?880:1500,.82);
      }
    }
  }

  function scheduleBonusBattleCycle(ctx,destination,startAt,config) {
    const beat=60/config.bpm, bar=beat*4;
    const riff=[0,null,0,3,0,null,1,6];
    for(let b=0;b<config.bars;b++){
      const at=startAt+b*bar, root=config.roots[b%config.roots.length];
      const fifth=root*Math.pow(2,7/12), minor=root*Math.pow(2,3/12);
      battleMusicTone(ctx,destination,at,bar*.97,root/2,.043,'sine',{cutoff:620,attack:.12,release:.45});
      battleMusicTone(ctx,destination,at+.03,bar*.92,root,.016,'sawtooth',{cutoff:720,attack:.18,release:.55,detune:-5});
      battleMusicTone(ctx,destination,at+.06,bar*.88,minor*2,.0065,'triangle',{cutoff:1450,attack:.26,release:.62});
      battleMusicTone(ctx,destination,at+.08,bar*.86,fifth*2,.0055,'sawtooth',{cutoff:1350,attack:.28,release:.60,detune:6});
      for(let step=0;step<8;step++){
        const note=riff[(step+b)%riff.length];
        const noteAt=at+step*(beat/2);
        if(note!==null){
          const freq=root*2*Math.pow(2,note/12);
          battleMusicTone(ctx,destination,noteAt,beat*.34,freq,.022,'sawtooth',{drive:true,cutoff:960,attack:.008,release:.10});
        }
        if(step%2===0) battleMusicNoise(ctx,destination,noteAt+.02,.055,.012,'highpass',4300,.45);
      }
      battleMusicKick(ctx,destination,at,b%2===0?.15:.13);
      battleMusicKick(ctx,destination,at+beat*2,.12);
      battleMusicSnare(ctx,destination,at+beat,.046);
      battleMusicSnare(ctx,destination,at+beat*3,.052);
      if(b===3||b===7) battleMusicRiser(ctx,destination,at+bar*.55,bar*.43,.016);
    }
  }

  function scheduleThemedBonusBattleCycle(ctx,destination,startAt,config,style) {
    const profile=BONUS_BATTLE_MUSIC_PROFILES[style]||BONUS_BATTLE_MUSIC_PROFILES.bonusMars;
    const beat=60/config.bpm,bar=beat*4;
    const riff=profile.riff||[0,null,0,3,0,null,1,6];
    const lead=profile.lead||[12,10,7,5];
    for(let b=0;b<config.bars;b++){
      const at=startAt+b*bar,root=config.roots[b%config.roots.length];
      const third=root*Math.pow(2,(profile.third||3)/12),fifth=root*Math.pow(2,7/12);
      battleMusicTone(ctx,destination,at,bar*.98,root/2,.048,'sine',{cutoff:650,attack:.06,release:.32});
      battleMusicTone(ctx,destination,at+.015,bar*.94,root,.0165,'sawtooth',{cutoff:Math.max(760,profile.cutoff*.68),attack:.12,release:.44,detune:-5});
      if(b%2===0){
        battleMusicTone(ctx,destination,at+.04,bar*1.84,third*2,.0068,'triangle',{cutoff:profile.cutoff*1.12,attack:.25,release:.66});
        battleMusicTone(ctx,destination,at+.07,bar*1.80,fifth*2,.0062,'sawtooth',{cutoff:profile.cutoff,attack:.28,release:.64,detune:7});
      }
      for(let step=0;step<16;step++){
        const note=riff[(step+b*3)%riff.length],noteAt=at+step*(beat/4);
        if(note!==null&&note!==undefined){
          const octave=(step%8===6&&style!=='bonusFoundry')?4:2;
          const freq=root*octave*Math.pow(2,note/12);
          const amp=octave===4?.0125:.027;
          battleMusicTone(ctx,destination,noteAt,beat*(profile.pulse===2?.20:.24),freq,amp,'sawtooth',{drive:true,cutoff:profile.cutoff,attack:.004,release:.060,detune:step%2?-4:4});
        }
        if(step%(profile.pulse||4)===0) battleMusicNoise(ctx,destination,noteAt+.004,.036,.0095,'highpass',profile.noise,.34);
      }

      if(profile.kick==='double'){
        for(let q=0;q<4;q++){battleMusicKick(ctx,destination,at+q*beat,q===0?.19:.145);battleMusicKick(ctx,destination,at+q*beat+beat*.5,.092);}
      }else if(profile.kick==='machine'){
        for(let q=0;q<8;q++) battleMusicKick(ctx,destination,at+q*(beat/2),q%4===0?.18:(q%2===0?.118:.070));
      }else if(profile.kick==='lurch'){
        battleMusicKick(ctx,destination,at,.18);battleMusicKick(ctx,destination,at+beat*.75,.09);battleMusicKick(ctx,destination,at+beat*2,.15);battleMusicKick(ctx,destination,at+beat*2.75,.10);
      }else if(profile.kick==='void'){
        battleMusicKick(ctx,destination,at,.16);battleMusicKick(ctx,destination,at+beat*1.5,.105);battleMusicKick(ctx,destination,at+beat*3,.135);
      }else if(profile.kick==='wide'){
        battleMusicKick(ctx,destination,at,.17);battleMusicKick(ctx,destination,at+beat*2,.145);battleMusicNoise(ctx,destination,at+beat*3.5,.15,.018,'bandpass',2200,.5);
      }else{
        for(let q=0;q<4;q++) battleMusicKick(ctx,destination,at+q*beat,q===0?.18:.115);
      }
      battleMusicSnare(ctx,destination,at+beat,.058);
      battleMusicSnare(ctx,destination,at+beat*3,.064);

      if(b===1||b===5){
        for(let i=0;i<lead.length;i++){
          const freq=root*4*Math.pow(2,lead[i]/12);
          battleMusicTone(ctx,destination,at+beat*(2.05+i*.42),beat*.32,freq,.0095,'triangle',{cutoff:profile.cutoff*1.45,attack:.010,release:.13});
        }
      }
      if(b===3||b===7){
        battleMusicRiser(ctx,destination,at+bar*.46,bar*.52,profile.air||.022);
        battleMusicNoise(ctx,destination,at+bar*.93,.22,.027,'bandpass',Math.max(650,profile.noise*.18),.8);
      }
    }
  }

  function scheduleUltro1BattleCycle(ctx,destination,startAt,config) {
    const beat=60/config.bpm, bar=beat*4;
    const riff=[0,0,null,3,0,6,0,null,0,1,0,null,6,3,0,0];
    for(let b=0;b<config.bars;b++){
      const at=startAt+b*bar,root=config.roots[b%config.roots.length];
      const minor=root*Math.pow(2,3/12),fifth=root*Math.pow(2,7/12);
      battleMusicTone(ctx,destination,at,bar*.98,root/2,.050,'sine',{cutoff:620,attack:.055,release:.30});
      if(b%2===0){
        battleMusicTone(ctx,destination,at+.04,bar*1.85,root*2,.009,'sawtooth',{cutoff:1450,attack:.32,release:.7,detune:-7});
        battleMusicTone(ctx,destination,at+.06,bar*1.82,minor*2,.007,'triangle',{cutoff:1700,attack:.34,release:.72});
        battleMusicTone(ctx,destination,at+.08,bar*1.78,fifth*2,.0065,'sawtooth',{cutoff:1500,attack:.36,release:.7,detune:8});
      }
      for(let step=0;step<16;step++){
        const note=riff[(step+b*2)%riff.length],noteAt=at+step*(beat/4);
        if(note!==null){
          const freq=root*2*Math.pow(2,note/12);
          battleMusicTone(ctx,destination,noteAt,beat*.19,freq,.030,'sawtooth',{drive:true,cutoff:1220,attack:.005,release:.065,detune:step%2?-4:4});
        }
        if(step%2===0) battleMusicNoise(ctx,destination,noteAt+.005,.038,.010,'highpass',5200,.35);
      }
      for(let q=0;q<4;q++) battleMusicKick(ctx,destination,at+q*beat,q===0?.18:.135);
      battleMusicKick(ctx,destination,at+beat*.5,.085);
      battleMusicKick(ctx,destination,at+beat*2.5,.095);
      battleMusicSnare(ctx,destination,at+beat,.065);
      battleMusicSnare(ctx,destination,at+beat*3,.072);
      if(b===1||b===5){
        const stab=root*4*Math.pow(2,6/12);
        battleMusicTone(ctx,destination,at+beat*3.15,beat*.62,stab,.011,'triangle',{cutoff:2400,attack:.018,release:.22});
      }
      if(b===3||b===7) battleMusicRiser(ctx,destination,at+bar*.50,bar*.49,.022);
    }
  }

  function scheduleUltro2BattleCycle(ctx,destination,startAt,config) {
    const beat=60/config.bpm,bar=beat*4;
    const riff=[0,0,1,0,6,0,null,1,0,0,6,7,1,0,6,0];
    for(let b=0;b<config.bars;b++){
      const at=startAt+b*bar,root=config.roots[b%config.roots.length];
      const minor=root*Math.pow(2,3/12),tritone=root*Math.pow(2,6/12),fifth=root*Math.pow(2,7/12);
      battleMusicTone(ctx,destination,at,bar*.99,root/2,.055,'sine',{cutoff:700,attack:.035,release:.25});
      battleMusicTone(ctx,destination,at+.01,bar*.96,tritone,.012,'sawtooth',{cutoff:920,attack:.12,release:.42,detune:-9});
      if(b%2===0){
        battleMusicTone(ctx,destination,at+.03,bar*1.90,root*2,.010,'sawtooth',{cutoff:1800,attack:.22,release:.68,detune:-10});
        battleMusicTone(ctx,destination,at+.05,bar*1.87,minor*2,.0085,'triangle',{cutoff:2100,attack:.24,release:.70});
        battleMusicTone(ctx,destination,at+.07,bar*1.83,fifth*2,.0078,'sawtooth',{cutoff:1850,attack:.26,release:.68,detune:11});
      }
      for(let step=0;step<16;step++){
        const note=riff[(step+b*3)%riff.length],noteAt=at+step*(beat/4);
        if(note!==null){
          const octave=(step===4||step===12)?4:2;
          const freq=root*octave*Math.pow(2,note/12);
          battleMusicTone(ctx,destination,noteAt,beat*.18,freq,octave===4?.017:.034,'sawtooth',{drive:true,cutoff:octave===4?2050:1380,attack:.004,release:.055,detune:step%2?-6:6});
        }
        battleMusicNoise(ctx,destination,noteAt+.004,.030,step%2===0?.012:.008,'highpass',6100,.30);
      }
      for(let q=0;q<4;q++){
        battleMusicKick(ctx,destination,at+q*beat,q===0?.205:.155);
        if(q!==3) battleMusicKick(ctx,destination,at+q*beat+beat*.5,.105);
      }
      battleMusicSnare(ctx,destination,at+beat,.080);
      battleMusicSnare(ctx,destination,at+beat*3,.088);
      const highBase=root*8;
      if(b===2||b===6){
        [0,1,6,7].forEach((semitone,i)=>battleMusicTone(ctx,destination,at+beat*(i+.08),beat*.44,highBase*Math.pow(2,semitone/12),.0095,'triangle',{cutoff:3100,attack:.012,release:.16}));
      }
      if(b===3||b===7){
        battleMusicRiser(ctx,destination,at+bar*.40,bar*.59,.030);
        battleMusicNoise(ctx,destination,at+bar*.94,.34,.055,'bandpass',720,.9);
      }
    }
  }

  function scheduleBattleMusicCycle(ctx,startAt,style) {
    if(!ctx||!battleMusicBus) return 8;
    const config=BATTLE_MUSIC_CONFIG[style]||BATTLE_MUSIC_CONFIG.bonus;
    if(style==='ultro2') scheduleUltro2BattleCycle(ctx,battleMusicBus,startAt,config);
    else if(style==='ultro1') scheduleUltro1BattleCycle(ctx,battleMusicBus,startAt,config);
    else if(style.startsWith('campaign')) scheduleCampaignCalmCycle(ctx,battleMusicBus,startAt,config,style);
    else if(style.startsWith('bonus')&&BONUS_BATTLE_MUSIC_PROFILES[style]) scheduleThemedBonusBattleCycle(ctx,battleMusicBus,startAt,config,style);
    else scheduleBonusBattleCycle(ctx,battleMusicBus,startAt,config);
    return (60/config.bpm)*4*config.bars;
  }

  function scheduleNextBattleMusicCycles(generation) {
    if(!battleMusicRunning||generation!==battleMusicGeneration||!menuMusicCtx||!battleMusicStyle) return;
    const ctx=menuMusicCtx;
    const config=BATTLE_MUSIC_CONFIG[battleMusicStyle]||BATTLE_MUSIC_CONFIG.bonus;
    const cycle=(60/config.bpm)*4*config.bars;
    while(battleMusicCycleStart<ctx.currentTime+cycle*1.25){
      scheduleBattleMusicCycle(ctx,battleMusicCycleStart,battleMusicStyle);
      battleMusicCycleStart+=cycle;
    }
    clearTimeout(battleMusicTimer);
    battleMusicTimer=setTimeout(()=>scheduleNextBattleMusicCycles(generation),Math.max(800,cycle*430));
  }

  function stopBattleMusic(fadeSeconds=.85) {
    battleMusicRunning=false; battleMusicGeneration++;
    clearTimeout(battleMusicTimer); battleMusicTimer=null;
    battleMusicStyle='';
    if(!menuMusicCtx||!battleMusicBus) return;
    const bus=battleMusicBus; battleMusicBus=null;
    const now=menuMusicCtx.currentTime,fade=Math.max(.08,Number(fadeSeconds)||.85);
    bus.gain.cancelScheduledValues(now);
    bus.gain.setValueAtTime(Math.max(.0001,Number(bus.gain.value)||.0001),now);
    bus.gain.exponentialRampToValueAtTime(.0001,now+fade);
    setTimeout(()=>{try{bus.disconnect();}catch(_){}},(fade+.18)*1000);
  }

  function startBattleMusic(style='bonus') {
    const desired=BATTLE_MUSIC_CONFIG[style]?style:'bonus';
    const ctx=getMenuMusicContext();
    if(!ctx||!menuMusicMaster) return;
    try{if(ctx.state==='suspended')ctx.resume();}catch(_){}
    if(battleMusicRunning&&battleMusicStyle===desired&&battleMusicBus) return;
    if(battleMusicBus) stopBattleMusic(.42);
    battleMusicRunning=true; battleMusicStyle=desired; battleMusicGeneration++;
    const generation=battleMusicGeneration,now=ctx.currentTime,config=BATTLE_MUSIC_CONFIG[desired];
    const bus=ctx.createGain();
    bus.gain.setValueAtTime(.0001,now);
    bus.gain.exponentialRampToValueAtTime(config.volume,now+.72);
    bus.connect(menuMusicMaster); battleMusicBus=bus; battleMusicCycleStart=now+.06;
    scheduleNextBattleMusicCycles(generation);
  }

  function campaignMusicStyleForCurrentLevel() {
    const level=clamp(Math.floor(Number(state?.level)||1),1,LEVELS.length);
    const info=LEVELS[level-1]||{};
    const theme=String(info.theme||'');
    if(theme==='desert') return 'campaignDesert';
    if(['mixedWater','polarOil','floodedCity','hydroDam','coastalFort'].includes(theme)) return 'campaignWater';
    if(['exclusionZone','mudFront','stormfront','highmountain'].includes(theme)) return 'campaignGreen';
    if(['megacityNight','underground','ashlands'].includes(theme)) return 'campaignNight';
    if(['slag','railHub','airfield','junkyard','armsFactory','lastCapital','citadel'].includes(theme)) return 'campaignSteel';
    // Ранние карты ещё не все имеют theme: даём им разнообразие вручную.
    if([7,9,17,21,22].includes(level)) return 'campaignWater';
    if([8,15,16,23].includes(level)) return 'campaignGreen';
    if([5,11,18].includes(level)) return 'campaignNight';
    if([4,10,13,14,20,24].includes(level)) return 'campaignSteel';
    const rotation=['campaignGreen','campaignSteel','campaignWater','campaignNight'];
    return rotation[(level-1)%rotation.length];
  }

  function desiredBattleMusicStyle() {
    if(!gameStarted||!state||state.gameOver||isPvpMode()) return '';
    if(state.inBonusLevel){
      if(state.bonusLevelKey===SECRET_BONUS_LEVEL_KEY_STAGE_3) {
        const alive=(state.enemies||[]).some(e=>e?.alive&&e.enemyType==='ultroOmega');
        return alive ? 'ultro3' : '';
      }
      if(state.bonusLevelKey===SECRET_BONUS_LEVEL_KEY_STAGE_2) {
        const alive=(state.enemies||[]).some(e=>e?.alive&&e.enemyType==='ultroAscended');
        return alive ? 'ultro2' : '';
      }
      if(state.bonusLevelKey===SECRET_BONUS_LEVEL_KEY) {
        const alive=(state.enemies||[]).some(e=>e?.alive&&e.enemyType==='ultroMaster');
        return alive ? 'ultro1' : '';
      }
      return BONUS_BATTLE_MUSIC_STYLES[state.bonusLevelKey] || 'bonus';
    }
    if(state.bossFight) return 'campaignBoss';
    return campaignMusicStyleForCurrentLevel();
  }

  function syncBattleMusicForState() {
    const desired=desiredBattleMusicStyle();
    if (desired === 'ultro1' || desired === 'ultro2' || desired === 'ultro3') {
      // The supplied sampled ULTRO soundtrack replaces the old procedural ULTRO themes.
      if (battleMusicRunning || battleMusicBus) stopBattleMusic(.30);
      startUltroBossMusic(desired);
      return;
    }
    if (ultroBossMusicFading) return;
    if (ultroBossMusicStyle || (ultroBossMusicAudio && !ultroBossMusicAudio.paused)) {
      // После завершения ULTRO-боя музыка мягко затихает и только затем освобождает канал.
      stopUltroBossMusic(true, 1.8);
      return;
    }
    if(!desired){if(battleMusicRunning||battleMusicBus)stopBattleMusic(.75);return;}
    if(!battleMusicRunning||battleMusicStyle!==desired||!battleMusicBus) startBattleMusic(desired);
  }
