          if(!inBuild && (wx<8||wy<7||wx>BASE_WORLD_COLS-9||wy>BASE_WORLD_ROWS-8)){ r=72; g=127; bv=66; }
          if(wx<9 && wy>BASE_WORLD_ROWS-11){ r=80; g=130; bv=68; }
          if(wx>BASE_WORLD_COLS-10 && wy<10){ r=74; g=129; bv=72; }
          if(bank>.01 && !inBuild){ r=164; g=150; bv=106; }
          r += Math.floor((n1-.5)*18 + (n2-.5)*9 - canyon*18 + bank*10);
          g += Math.floor((n2-.5)*18 + (n3-.5)*10 - canyon*20 + bank*10);
