  function drawBaseMissileComplexVentSmoke(left,top,dw,dh,s,now,overlay=false){
    if(!isLocalStrategicBasePowered()) return;
    const seconds=now*.001;
    const vents=[
      {x:.535,y:.735,dx:-1.06,dy:.20,period:5.2,window:1.95,offset:.20,count:14,size:16},
      {x:.570,y:.748,dx:1.00,dy:.22,period:7.4,window:2.10,offset:2.65,count:15,size:17},
      {x:.552,y:.770,dx:-.18,dy:.84,period:10.6,window:2.35,offset:6.20,count:16,size:18}
    ];
    baseCtx.save();
    if(overlay) baseCtx.globalCompositeOperation='screen';
    for(let vi=0;vi<vents.length;vi++){
      const v=vents[vi];
      const phase=(seconds+v.offset+s.x*.17+s.y*.11)%v.period;
      if(phase>v.window) continue;
      const burst=phase/v.window;
      const startX=left+dw*v.x,startY=top+dh*v.y;
      for(let i=0;i<v.count;i++){
        const age=burst-i*.05;
        if(age<0||age>1) continue;
        const travel=(22+92*age);
        const wobble=Math.sin(seconds*3.0+i*1.71+vi)*6.8;
        const px=startX+v.dx*travel+wobble*(-v.dy);
        const py=startY+v.dy*travel+wobble*v.dx-age*(overlay?10:8);
        const rr=(v.size+age*22)*(1+.11*Math.sin(i*1.7+seconds));
        const alpha=(1-age)*(overlay ? (.16+.04*(i%3)) : (.34+.08*(i%4)));
        const g=baseCtx.createRadialGradient(px-rr*.20,py-rr*.22,0,px,py,rr);
        g.addColorStop(0,`rgba(244,248,244,${alpha*.92})`);
        g.addColorStop(.28,`rgba(184,190,186,${alpha*.82})`);
        g.addColorStop(.58,`rgba(118,124,122,${alpha*.66})`);
        g.addColorStop(.84,`rgba(76,80,80,${alpha*.44})`);
        g.addColorStop(1,'rgba(48,52,52,0)');
        baseCtx.fillStyle=g;
        baseCtx.beginPath();
        baseCtx.ellipse(px,py,rr*1.34,rr*.90,Math.atan2(v.dy,v.dx)*.16,0,Math.PI*2);
        baseCtx.fill();
      }
      const jetA=Math.max(0,1-burst*1.1);
      if(jetA>0){
        const jet=baseCtx.createLinearGradient(startX,startY,startX+v.dx*40,startY+v.dy*40);
        jet.addColorStop(0,`rgba(250,252,248,${(overlay?.16:.42)*jetA})`);
        jet.addColorStop(.32,`rgba(205,214,208,${(overlay?.11:.28)*jetA})`);
        jet.addColorStop(.68,`rgba(148,155,151,${(overlay?.07:.16)*jetA})`);
        jet.addColorStop(1,'rgba(100,104,102,0)');
        baseCtx.strokeStyle=jet;baseCtx.lineWidth=overlay?8.5:12.5;baseCtx.lineCap='round';
        baseCtx.beginPath();baseCtx.moveTo(startX,startY);baseCtx.lineTo(startX+v.dx*42,startY+v.dy*42);baseCtx.stroke();
      }
    }
    baseCtx.restore();
  }

