    const builtType=selectedBaseBuild;
    baseCoins-=def.cost;baseStructures.push({id:`b${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`,type:builtType,x,y,...(['finance','logistics','tech','research'].includes(builtType)?{level:1}:{})});
