  function normalizeInventory(raw) {
    const obj = raw && typeof raw === 'object' ? raw : {};
    const sourceCases = obj.casesByType && typeof obj.casesByType === 'object' ? obj.casesByType : null;
    const casesByType = {};
    for (const caseType of Object.keys(CASE_TYPES)) {
      const legacyValue = caseType === 'supply' ? Number(obj.cases) || 0 : 0;
      const storedValue = sourceCases ? Number(sourceCases[caseType]) || 0 : legacyValue;
      casesByType[caseType] = Math.max(0, Math.floor(storedValue));
    }
    const normalizeStoredReward = reward => {
      if(!reward || typeof reward !== 'object') return null;
      if(reward.type === 'points' && Number(reward.amount) > 0) return {type:'points', amount:Math.floor(Number(reward.amount))};
      if(reward.type === 'tank' && PLAYER_TYPES[reward.tank]) return {type:'tank', tank:reward.tank};
      return null;
    };
    let pendingReward = null;
    if (Number(obj.pendingReward) > 0) {
      pendingReward = {caseType:'supply', reward:{type:'points', amount:Math.floor(Number(obj.pendingReward))}};
    } else if (obj.pendingReward && typeof obj.pendingReward === 'object') {
      const caseType = CASE_TYPES[obj.pendingReward.caseType] ? obj.pendingReward.caseType : 'supply';
      if(Array.isArray(obj.pendingReward.rewards)) {
        const rewards=obj.pendingReward.rewards.map(normalizeStoredReward).filter(Boolean).slice(0,MAX_CASE_BULK_PURCHASE);
        if(rewards.length) pendingReward={caseType,rewards};
      } else {
        const reward=normalizeStoredReward(obj.pendingReward.reward);
        if(reward) pendingReward={caseType,reward};
      }
    }
    return {casesByType, items:obj.items&&typeof obj.items==='object'?obj.items:{}, recent:Array.isArray(obj.recent)?obj.recent.slice(0,12):[], pendingReward};
  }

  function loadInventory() {
    try { playerInventory = normalizeInventory(JSON.parse(localStorage.getItem(INVENTORY_KEY) || '{}')); }
    catch (_) { playerInventory = normalizeInventory({}); }
  }
  function saveInventory() { try { localStorage.setItem(INVENTORY_KEY, JSON.stringify(playerInventory)); } catch (_) {} }
  function getCaseCount(caseType='supply') { return Math.max(0,Math.floor(Number(playerInventory.casesByType?.[caseType])||0)); }
  function getTotalCaseCount() { return Object.keys(CASE_TYPES).reduce((sum,key)=>sum+getCaseCount(key),0); }
  function addLocalCases(count,caseType='supply') {
    const value=Math.max(0,Math.floor(Number(count)||0));
    if(!value||!CASE_TYPES[caseType]) return;
    if(!playerInventory.casesByType||typeof playerInventory.casesByType!=='object') playerInventory.casesByType={};
    playerInventory.casesByType[caseType]=getCaseCount(caseType)+value;
    saveInventory(); refreshCases();
  }
  function grantCaseToSlot(slot,count=1,caseType='supply') {
    if(!state||!CASE_TYPES[caseType]) return;
    const targetSlot=networkMode==='lan'?normalizePlayerSlot(slot):1;
    const value=Math.max(0,Math.floor(Number(count)||0));
    if(!value) return;
    const key=caseKeyForSlot(targetSlot,caseType);
    state[key]=Number(state[key]||0)+value;
    recordCareerStatForSlot(targetSlot,'casesEarned',value);
    if(networkMode==='solo'||(networkIsHost&&targetSlot===1)) addLocalCases(value,caseType);
  }

  function chooseCaseReward(caseType='supply') {
    const type=CASE_TYPES[caseType]||CASE_TYPES.supply;
    let roll=Math.random()*100;
    for(const reward of type.rewards){roll-=reward.chance;if(roll<0)return reward;}
    return type.rewards[0];
  }
  function rewardClass(reward){return reward.rarity==='platinum'?'rarity-platinum':reward.rarity==='gold'?'rarity-gold':reward.rarity==='red'?'rarity-red':reward.rarity==='purple'?'rarity-purple':'rarity-common';}
  function makeCaseCard(reward){
    const card=document.createElement('div'); card.className=`case-card ${rewardClass(reward)}`;
    if(reward.type==='points'){
      const coin=document.createElement('div'); coin.className='coin tank-coin'; const glyph=document.createElement('span'); glyph.className='coin-glyph'; glyph.textContent='T'; coin.append(glyph);
      const value=document.createElement('div'); value.className='reward-value'; value.textContent=`${reward.points.toLocaleString('ru-RU')} очк.`;
      card.append(coin,value);
    } else if(reward.type==='tank'){
      const tankName = PLAYER_TYPES[reward.tank]?.name || 'Танк';
      const tank=document.createElement('div'); tank.className='case-tank-reward'; tank.setAttribute('aria-label',`Танк ${tankName}`);
      const preview=document.createElement('canvas'); preview.className='case-tank-preview'; preview.width=108; preview.height=84; preview.dataset.playerType=reward.tank; preview.setAttribute('aria-hidden','true');
      drawTankPreview(preview,reward.tank);
      tank.append(preview);
      const value=document.createElement('div'); value.className='reward-value'; value.textContent=tankName;
      card.append(tank,value);
    }
    return card;
  }
  function renderCaseRewards(caseType){
    if(!caseRewardsListEl)return;
    const type=CASE_TYPES[caseType]; caseRewardsListEl.replaceChildren(); if(!type)return;
    for(const reward of type.rewards){
      const row=document.createElement('div'); row.className=`case-reward-row ${rewardClass(reward)}`;
      const label=document.createElement('span');
      if(reward.type==='tank' && PLAYER_TYPES[reward.tank]){
        const tankName = PLAYER_TYPES[reward.tank].name;
        label.className='case-label-with-icon';
        const icon=document.createElement('canvas'); icon.className='mini-case-tank-preview'; icon.width=108; icon.height=84; icon.dataset.playerType=reward.tank; icon.setAttribute('aria-hidden','true');
        drawTankPreview(icon,reward.tank);
        const text=document.createElement('span'); text.textContent=`Танк «${tankName}»`;
        label.append(icon,text);
      } else {
        label.textContent=reward.type==='points'?`${reward.points.toLocaleString('ru-RU')} очков`:'Награда';
      }
      const chance=document.createElement('span'); chance.textContent=`${Number(reward.chance).toLocaleString('ru-RU')}%`; row.append(label,chance); caseRewardsListEl.appendChild(row);
    }
  }
  function clearCaseAnimationTimers(){
    if(caseAnimationTimer) clearTimeout(caseAnimationTimer); caseAnimationTimer=null;
    for(const timer of caseStatusTimers) clearTimeout(timer); caseStatusTimers=[];
    if(caseTrackAnimation){try{caseTrackAnimation.cancel();}catch(_){} caseTrackAnimation=null;}
    if(caseAnimationRaf){cancelAnimationFrame(caseAnimationRaf);caseAnimationRaf=0;}
  }
  function showCaseInventory(){
    if(caseOpening)return; selectedCaseType=null; caseInventoryViewEl?.classList.add('active'); caseOpeningViewEl?.classList.remove('active'); refreshCases();
  }
  function selectCaseType(caseType){
    if(caseOpening||!CASE_TYPES[caseType])return;
    selectedCaseType=caseType; caseInventoryViewEl?.classList.remove('active'); caseOpeningViewEl?.classList.add('active');
    if(caseTrackEl) caseTrackEl.replaceChildren();
    if(batchCaseGridEl){batchCaseGridEl.replaceChildren();batchCaseGridEl.className='batch-case-grid';}
    batchCaseModalEl?.classList.add('hidden');
    if(batchCaseModalEl) batchCaseModalEl.style.removeProperty('display');
    document.body.classList.remove('batch-case-open');
    singleCaseOpeningEl?.classList.remove('hidden');
    if(caseStatusEl){caseStatusEl.classList.remove('winner');caseStatusEl.textContent=getCaseCount(caseType)>0?'Выбери ×1, ×5, ×10 или открой все.':'В инвентаре нет кейсов этого типа.';}
    refreshCases();
  }
  function refreshCases(){
    ensureSecretCaseUI(); const secretCountEl=document.getElementById('secretCaseCount'); if(secretCountEl) secretCountEl.textContent=String(getCaseCount('secret'));
    const caseType=selectedCaseType&&CASE_TYPES[selectedCaseType]?selectedCaseType:null;
    if(caseType&&caseTrackEl&&!caseOpening&&caseTrackEl.children.length===0){
      const rewards=CASE_TYPES[caseType].rewards; for(const reward of [...rewards,...rewards]) caseTrackEl.appendChild(makeCaseCard(reward));
      caseTrackEl.style.transition='none'; caseTrackEl.style.transform='translate3d(-180px,0,0)';
    }
    if(caseCountEl) caseCountEl.textContent=String(getTotalCaseCount());
    if(supplyCaseCountEl) supplyCaseCountEl.textContent=String(getCaseCount('supply'));
    if(harkonnenCaseCountEl) harkonnenCaseCountEl.textContent=String(getCaseCount('harkonnen'));
    if(atreidesCaseCountEl) atreidesCaseCountEl.textContent=String(getCaseCount('atreides'));
    if(ordosCaseCountEl) ordosCaseCountEl.textContent=String(getCaseCount('ordos'));
    if(emperorCaseCountEl) emperorCaseCountEl.textContent=String(getCaseCount('emperor'));
    if(casePointBalanceEl) casePointBalanceEl.textContent=getPointBalance().toLocaleString('ru-RU');
    if(caseType){const type=CASE_TYPES[caseType]; if(selectedCaseNameEl)selectedCaseNameEl.textContent=type.name; if(selectedCaseDescriptionEl)selectedCaseDescriptionEl.textContent=type.description; if(selectedCaseCountEl)selectedCaseCountEl.textContent=String(getCaseCount(caseType)); renderCaseRewards(caseType);}
    const available=caseType?getCaseCount(caseType):0;
    if(openCaseBtn){openCaseBtn.disabled=caseOpening||!caseType||available<1;openCaseBtn.textContent=caseOpening?'Открываются…':'Открыть ×1';}
    if(openCase5Btn){openCase5Btn.disabled=caseOpening||!caseType||available<5;openCase5Btn.textContent=caseOpening?'Открываются…':'Открыть ×5';}
    if(openCase10Btn){openCase10Btn.disabled=caseOpening||!caseType||available<10;openCase10Btn.textContent=caseOpening?'Открываются…':'Открыть ×10';}
    if(openCaseAllBtn){openCaseAllBtn.disabled=caseOpening||!caseType||available<1;openCaseAllBtn.textContent=caseOpening?'Открываются…':`Открыть все (${available})`;}
    if(backToCaseInventoryBtn) backToCaseInventoryBtn.disabled=caseOpening;
  }
  function storedCaseReward(reward){
    if(reward?.type==='points') return {type:'points',amount:Math.max(0,Math.floor(Number(reward.points ?? reward.amount)||0))};
    if(reward?.type==='tank'&&PLAYER_TYPES[reward.tank]) return {type:'tank',tank:reward.tank};
    return null;
  }
  function settlePendingCaseReward(showResult=true){
    const pending=playerInventory.pendingReward; if(!pending||typeof pending!=='object')return null;
    const rewards=(Array.isArray(pending.rewards)?pending.rewards:[pending.reward]).filter(Boolean);
    let directPoints=0, totalPoints=0, tankRewards=0, newTanks=0, duplicateTanks=0, duplicateCompensation=0;
    const newTankCounts={}, duplicateTankCounts={}, pointRewardCounts={};
    for(const reward of rewards){
      if(reward?.type==='points'){
        const basePoints=Math.max(0,Math.floor(Number(reward.amount)||0));
        const points=applyFinanceBonusToDirectPoints(basePoints);
        if(points){
          careerPoints+=points; directPoints+=points; totalPoints+=points;
          pointRewardCounts[points]=(pointRewardCounts[points]||0)+1;
          playerInventory.recent.unshift({type:'points',amount:points,caseType:pending.caseType||'supply',date:Date.now()});
        }
      } else if(reward?.type==='tank'){
        const tankKey=PLAYER_TYPES[reward.tank]?reward.tank:null;
        if(tankKey){
          const newlyUnlocked=grantTankOwnership(tankKey,false);
          tankRewards++;
          if(newlyUnlocked){
            newTanks++;
            newTankCounts[tankKey]=(newTankCounts[tankKey]||0)+1;
          }else{
            duplicateTanks++;
            duplicateTankCounts[tankKey]=(duplicateTankCounts[tankKey]||0)+1;
            const compensation=applyFinanceBonusToDirectPoints(duplicateTankCompensation(tankKey));
            careerPoints+=compensation;
            totalPoints+=compensation;
            duplicateCompensation+=compensation;
            playerInventory.recent.unshift({type:'points',amount:compensation,caseType:pending.caseType||'supply',reason:'duplicateTank',tank:tankKey,date:Date.now()});
          }
          playerInventory.recent.unshift({type:'tank',tank:tankKey,caseType:pending.caseType||'supply',duplicate:!newlyUnlocked,date:Date.now()});
        }
      }
    }
    const summary={
      caseType:pending.caseType||'supply',
      opened:rewards.length,
      directPoints,totalPoints,tankRewards,newTanks,duplicateTanks,duplicateCompensation,
      newTankCounts,duplicateTankCounts,pointRewardCounts,
      openAll:!!pending.openAll
    };
    playerInventory.recent=playerInventory.recent.slice(0,12);
    if(showResult&&caseStatusEl){
      caseStatusEl.classList.add('winner');
      if(rewards.length<=1){
        const reward=rewards[0];
        if(reward?.type==='points') caseStatusEl.textContent=`Получено: ${totalPoints.toLocaleString('ru-RU')} очков`;
        else if(reward?.type==='tank'){
          const tankKey=PLAYER_TYPES[reward.tank]?reward.tank:null;
          if(tankKey && duplicateTanks) caseStatusEl.textContent=`Танк ${PLAYER_TYPES[tankKey].name} уже открыт · компенсация ${duplicateCompensation.toLocaleString('ru-RU')} очков`;
          else if(tankKey) caseStatusEl.textContent=`Получен танк: ${PLAYER_TYPES[tankKey].name}`;
        }
      } else {
        const parts=[`Открыто кейсов: ${rewards.length}`];
        if(totalPoints) parts.push(`${totalPoints.toLocaleString('ru-RU')} очков`);
        if(tankRewards) parts.push(`танков: ${tankRewards}${newTanks!==tankRewards?` (новых ${newTanks})`:''}`);
        if(duplicateTanks) parts.push(`дубликатов: ${duplicateTanks} · компенсация ${duplicateCompensation.toLocaleString('ru-RU')}`);
        caseStatusEl.textContent=parts.join(' · ');
      }
    }
    if(totalPoints) careerStatAdd('pointsEarned', totalPoints);
    playerInventory.pendingReward=null; saveCareerPoints(); saveInventory(); syncAchievements(gameStarted); refreshTankPicker(); refreshShop(); refreshCases();
    return summary;
  }

  function closeCaseResultsModal(){
    caseResultsModalEl?.classList.add('hidden');
    if(caseResultsModalEl)caseResultsModalEl.setAttribute('aria-hidden','true');
  }
  function appendCaseResultSection(title, rows, className=''){
    if(!caseResultsDetailsEl||!rows?.length)return;
    const section=document.createElement('div');section.className='case-results-section';
    const h=document.createElement('h3');h.textContent=title;section.appendChild(h);
    const list=document.createElement('div');list.className='case-results-list';
    for(const rowText of rows){const row=document.createElement('div');row.textContent=rowText;if(className)row.className=className;list.appendChild(row);}
    section.appendChild(list);caseResultsDetailsEl.appendChild(section);
  }
  function showCaseResultsModal(summary){
    if(!summary||!caseResultsModalEl)return;
    const caseName=CASE_TYPES[summary.caseType]?.name||'Кейс';
    if(caseResultsTitleEl)caseResultsTitleEl.textContent=`${caseName} · итог открытия`;
    if(caseResultsSubtitleEl)caseResultsSubtitleEl.textContent=`Открыто ${summary.opened.toLocaleString('ru-RU')} кейсов · все награды уже зачислены`;
    if(caseResultsStatsEl){
      caseResultsStatsEl.replaceChildren();
      for(const [label,value] of [
        ['Открыто',summary.opened.toLocaleString('ru-RU')],
        ['Всего очков',summary.totalPoints.toLocaleString('ru-RU')],
        ['Новых танков',summary.newTanks.toLocaleString('ru-RU')],
        ['Чистые очки',summary.directPoints.toLocaleString('ru-RU')],
        ['Дубликатов',summary.duplicateTanks.toLocaleString('ru-RU')],
        ['Компенсация',summary.duplicateCompensation.toLocaleString('ru-RU')]
      ]){
        const card=document.createElement('div');card.className='case-results-stat';card.textContent=label;
        const b=document.createElement('b');b.textContent=value;card.appendChild(b);caseResultsStatsEl.appendChild(card);
      }
    }
    if(caseResultsDetailsEl)caseResultsDetailsEl.replaceChildren();
    const pointRows=Object.entries(summary.pointRewardCounts||{}).sort((a,b)=>Number(a[0])-Number(b[0])).map(([amount,count])=>`${Number(amount).toLocaleString('ru-RU')} очков × ${count}`);
    const newRows=Object.entries(summary.newTankCounts||{}).map(([key,count])=>`${PLAYER_TYPES[key]?.name||key}${count>1?` × ${count}`:''}`);
    const dupRows=Object.entries(summary.duplicateTankCounts||{}).map(([key,count])=>`${PLAYER_TYPES[key]?.name||key} × ${count} · компенсация ${(duplicateTankCompensation(key)*count).toLocaleString('ru-RU')} очков`);
    appendCaseResultSection('Награды очками',pointRows);
    appendCaseResultSection('Новые танки',newRows,'new-tank');
    appendCaseResultSection('Повторные танки',dupRows,'duplicate');
    if(!pointRows.length&&!newRows.length&&!dupRows.length)appendCaseResultSection('Награды',['Награды зачислены.']);
    caseResultsModalEl.classList.remove('hidden');caseResultsModalEl.setAttribute('aria-hidden','false');
  }

  function prepareCaseOpening(caseType,count,openAll=false){
    const available=getCaseCount(caseType);
    if(caseOpening||!CASE_TYPES[caseType]||available<count||count<1)return null;
    const rewards=Array.from({length:count},()=>chooseCaseReward(caseType));
    const storedRewards=rewards.map(storedCaseReward).filter(Boolean);
    if(storedRewards.length!==count)return null;
    playerInventory.casesByType[caseType]=available-count;
    playerInventory.pendingReward=count===1&&!openAll?{caseType,reward:storedRewards[0]}:{caseType,rewards:storedRewards,openAll:!!openAll};
    achievementStats.casesOpened = Math.max(0,Math.floor(Number(achievementStats.casesOpened)||0)) + count;
    saveAchievementStats();
    syncAchievements(gameStarted);
    saveInventory();
    caseOpening=true;document.body.classList.add('ut-cursor-wait');clearCaseAnimationTimers();
    if(caseStatusEl){caseStatusEl.classList.remove('winner');caseStatusEl.textContent=openAll?`Открываются все кейсы: ${count}…`:(count===1?'Лента быстро вращается…':`${count} кейсов открываются одновременно…`);}
    refreshCases();
    return rewards;
  }
  function openSingleCase(caseType,reward){
    if(!caseTrackEl||!caseViewportEl){caseOpening=false;document.body.classList.remove('ut-cursor-wait');settlePendingCaseReward(false);return;}
    singleCaseOpeningEl?.classList.remove('hidden');
    batchCaseModalEl?.classList.add('hidden');
    if(batchCaseGridEl){batchCaseGridEl.replaceChildren();batchCaseGridEl.className='batch-case-grid';}
    const totalCards=68, winningIndex=58; caseTrackEl.replaceChildren();
    for(let i=0;i<totalCards;i++){const item=i===winningIndex?reward:chooseCaseReward(caseType);caseTrackEl.appendChild(makeCaseCard(item));}
    caseTrackEl.style.transition='none';caseTrackEl.style.transform='translate3d(0,0,0)';void caseTrackEl.offsetWidth;
    const cardStride=94,cardCenter=43,viewportCenter=caseViewportEl.clientWidth/2,jitter=(Math.random()-.5)*22;
    const targetX=viewportCenter-(winningIndex*cardStride+cardCenter)+jitter,duration=9800;
    const startedAt=performance.now();
    const easeOutQuint=t=>1-Math.pow(1-t,5);
    const animateCaseTrack=now=>{
      if(!caseOpening)return;
      const progressTime=Math.min(1,Math.max(0,(now-startedAt)/duration));
      const progress=easeOutQuint(progressTime);
      caseTrackEl.style.transform=`translate3d(${(targetX*progress).toFixed(3)}px,0,0)`;
      if(progressTime<1){caseAnimationRaf=requestAnimationFrame(animateCaseTrack);return;}
      caseAnimationRaf=0;caseTrackEl.style.transform=`translate3d(${targetX.toFixed(3)}px,0,0)`;
      caseOpening=false;document.body.classList.remove('ut-cursor-wait');settlePendingCaseReward(true);refreshCases();
    };
    caseAnimationRaf=requestAnimationFrame(animateCaseTrack);
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening&&caseStatusEl)caseStatusEl.textContent='Лента начинает плавно замедляться…';},2500));
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening&&caseStatusEl)caseStatusEl.textContent='Скорость постепенно снижается…';},5200));
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening&&caseStatusEl)caseStatusEl.textContent='Почти остановилась…';},7900));
  }
  function caseRewardText(reward){
    if(reward?.type==='points') return `${Number(reward.points||0).toLocaleString('ru-RU')} очков`;
    if(reward?.type==='tank') return PLAYER_TYPES[reward.tank]?.name || 'Танк';
    return 'Награда';
  }
  function closeBatchCaseModal(){
    if(caseOpening)return;
    batchCaseModalEl?.classList.add('hidden');
    if(batchCaseModalEl){batchCaseModalEl.style.removeProperty('display');batchCaseModalEl.setAttribute('aria-hidden','true');}
    document.body.classList.remove('batch-case-open');
    if(batchCaseGridEl){batchCaseGridEl.replaceChildren();batchCaseGridEl.className='batch-case-grid';}
    if(batchCaseModalStatusEl){batchCaseModalStatusEl.textContent='';batchCaseModalStatusEl.classList.remove('winner');}
    singleCaseOpeningEl?.classList.remove('hidden');
  }
  function createBatchCaseSlot(caseType,reward,index){
    const slot=document.createElement('div');slot.className='batch-case-slot';
    const label=document.createElement('div');label.className='batch-case-label';label.textContent=String(index+1);
    const viewport=document.createElement('div');viewport.className='batch-case-viewport';
    const marker=document.createElement('div');marker.className='batch-case-marker';marker.setAttribute('aria-hidden','true');
    const track=document.createElement('div');track.className='batch-case-track';
    const result=document.createElement('div');result.className='batch-case-result';result.textContent='…';
    const totalCards=46,winningIndex=39;
    for(let i=0;i<totalCards;i++) track.appendChild(makeCaseCard(i===winningIndex?reward:chooseCaseReward(caseType)));
    viewport.append(marker,track);slot.append(label,viewport,result);
    return {slot,viewport,track,result,reward,winningIndex};
  }
  function openBatchCases(caseType,rewards,openAll=false){
    if(!batchCaseGridEl||!batchCaseModalEl){caseOpening=false;document.body.classList.remove('ut-cursor-wait');const summary=settlePendingCaseReward(false);if(openAll)showCaseResultsModal(summary);return;}
    singleCaseOpeningEl?.classList.add('hidden');
    document.body.classList.add('batch-case-open');
    batchCaseModalEl.classList.remove('hidden');
    batchCaseModalEl.style.display='flex';
    batchCaseModalEl.setAttribute('aria-hidden','false');
    batchCaseGridEl.replaceChildren();
    const visualRewards=rewards.slice(0,10);
    batchCaseGridEl.className=`batch-case-grid count-${visualRewards.length}`;
    if(batchCaseModalTitleEl) batchCaseModalTitleEl.textContent=openAll?`${CASE_TYPES[caseType]?.name||'Кейс'} · открыть все ×${rewards.length}`:`${CASE_TYPES[caseType]?.name||'Кейс'} · открытие ×${rewards.length}`;
    if(batchCaseModalSubtitleEl) batchCaseModalSubtitleEl.textContent=openAll?`Разыгрываются все ${rewards.length} кейсов · в анимации показано ${visualRewards.length} из ${rewards.length}`:(visualRewards.length===10?'10 отдельных горизонтальных рулеток · две колонки по пять':`${visualRewards.length} отдельных горизонтальных рулеток · каждая останавливается независимо`);
    if(batchCaseModalStatusEl){batchCaseModalStatusEl.classList.remove('winner');batchCaseModalStatusEl.textContent=openAll?`Рассчитываются все ${rewards.length} наград…`:'Ленты быстро вращаются…';}
    if(batchCaseCloseBtn) batchCaseCloseBtn.disabled=true;
    const entries=visualRewards.map((reward,index)=>createBatchCaseSlot(caseType,reward,index));
    for(const entry of entries)batchCaseGridEl.appendChild(entry.slot);
    void batchCaseGridEl.offsetWidth;
    const startedAt=performance.now();
    const maxDuration=8000;
    for(const [index,entry] of entries.entries()){
      const firstCard=entry.track.querySelector('.case-card');
      const cardWidth=firstCard?.getBoundingClientRect().width||72;
      const trackStyle=getComputedStyle(entry.track);
      const gap=parseFloat(trackStyle.columnGap||trackStyle.gap)||6;
      const stride=cardWidth+gap;
      const viewportCenter=entry.viewport.clientWidth/2;
      const jitter=(Math.random()-.5)*Math.min(16,cardWidth*.18);
      entry.targetX=viewportCenter-(entry.winningIndex*stride+cardWidth/2)+jitter;
      entry.duration=6800+((index*149)%760)+Math.random()*210;
      entry.track.style.transform='translate3d(0,0,0)';
    }
    const easeOutQuint=t=>1-Math.pow(1-t,5);
    const animateBatch=now=>{
      if(!caseOpening)return;
      let allDone=true;
      for(const entry of entries){
        const p=Math.min(1,Math.max(0,(now-startedAt)/entry.duration));
        if(p<1)allDone=false;
        const progress=easeOutQuint(p);
        entry.track.style.transform=`translate3d(${(entry.targetX*progress).toFixed(3)}px,0,0)`;
        if(p>=1&&!entry.slot.classList.contains('finished')){
          entry.slot.classList.add('finished');entry.result.textContent=caseRewardText(entry.reward);entry.result.classList.add(rewardClass(entry.reward));
        }
      }
      if(!allDone && now-startedAt<maxDuration){caseAnimationRaf=requestAnimationFrame(animateBatch);return;}
      for(const entry of entries){entry.track.style.transform=`translate3d(${entry.targetX.toFixed(3)}px,0,0)`;entry.slot.classList.add('finished');entry.result.textContent=caseRewardText(entry.reward);entry.result.classList.add(rewardClass(entry.reward));}
      caseAnimationRaf=0;caseOpening=false;document.body.classList.remove('ut-cursor-wait');
      const summary=settlePendingCaseReward(true);refreshCases();
      if(batchCaseModalStatusEl){batchCaseModalStatusEl.textContent=openAll?`Все ${rewards.length} кейсов открыты · награды зачислены`:'Все ленты остановились · награды зачислены';batchCaseModalStatusEl.classList.add('winner');}
      if(batchCaseCloseBtn) batchCaseCloseBtn.disabled=false;
      if(openAll){closeBatchCaseModal();showCaseResultsModal(summary);}
    };
    caseAnimationRaf=requestAnimationFrame(animateBatch);
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening){if(caseStatusEl)caseStatusEl.textContent='Все ленты начинают замедляться…';if(batchCaseModalStatusEl)batchCaseModalStatusEl.textContent='Все ленты начинают замедляться…';}},2100));
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening){if(caseStatusEl)caseStatusEl.textContent='Результаты уже близко…';if(batchCaseModalStatusEl)batchCaseModalStatusEl.textContent='Результаты уже близко…';}},4700));
    caseStatusTimers.push(setTimeout(()=>{if(caseOpening){if(caseStatusEl)caseStatusEl.textContent='Почти остановились…';if(batchCaseModalStatusEl)batchCaseModalStatusEl.textContent='Почти остановились…';}},6200));
  }
  function openCases(count=1){
    const caseType=selectedCaseType;
    if(!caseType||!CASE_TYPES[caseType])return;
    const openAll=count==='all';
    const available=getCaseCount(caseType);
    const requested=openAll?available:([1,5,10].includes(Number(count))?Number(count):1);
    if(requested<1)return;
    const rewards=prepareCaseOpening(caseType,requested,openAll);if(!rewards)return;
    if(requested===1&&!openAll)openSingleCase(caseType,rewards[0]);else openBatchCases(caseType,rewards,openAll);
  }
  function openCase(){openCases(1);}

  function applyDeveloperImmortality() {
    if (!state) return;
    const slot = getLocalPlayerSlot();
    state[devKeyForSlot(slot)] = developerMode;
  }


  function isDeveloperBaseImmortal() {
    if (!state || isPvpMode()) return false;
    return getActivePlayerSlots().some(slot => !!state[devKeyForSlot(slot)]);
  }


  function refreshDeveloperTools() {
    if (developerTabBtn) developerTabBtn.hidden = !developerMode;
    if (!developerMode) {
      if (document.getElementById('tab-developer')?.classList.contains('active')) switchSideTab('game');
      return;
    }
    if (developerLevelSelect && developerLevelSelect.options.length !== LEVELS.length) {
      developerLevelSelect.innerHTML = '';
      LEVELS.forEach((info, index) => {
        const option = document.createElement('option');
        option.value = String(index + 1);
        option.textContent = `${index + 1} — ${info.name}`;
        developerLevelSelect.appendChild(option);
      });
    }
    if (developerBonusLevelSelect && developerBonusLevelSelect.options.length !== BONUS_LEVELS.length) {
      developerBonusLevelSelect.innerHTML = '';
      BONUS_LEVELS.forEach((info, index) => {
        const option = document.createElement('option');
        option.value = info.key;
        option.textContent = `${index + 1} — ${info.name}`;
        developerBonusLevelSelect.appendChild(option);
      });
    }
    if (developerLevelSelect && state && !isPvpMode()) developerLevelSelect.value = String(clamp(Number(state.level) || 1, 1, LEVELS.length));
    if (developerBonusLevelSelect && state?.inBonusLevel && state.bonusLevelKey) developerBonusLevelSelect.value = state.bonusLevelKey;
    const canJump = !!(developerMode && gameStarted && state && !isPvpMode() && (networkMode !== 'lan' || networkIsHost));
    if (developerJumpBtn) developerJumpBtn.disabled = !canJump;
    if (developerBonusJumpBtn) developerBonusJumpBtn.disabled = !canJump;
    if (developerStatusEl) {
      developerStatusEl.textContent = !gameStarted
        ? 'Сначала запусти игру.'
        : (isPvpMode()
          ? 'Выбор локации доступен в кампании.'
          : (networkMode === 'lan' && !networkIsHost
            ? 'В LAN мгновенно менять локацию может только ведущий.'
            : (state?.inBonusLevel
              ? `Тест бонусного уровня: ${getBonusLevelInfo(state.bonusLevelKey).name}.`
              : `Текущая локация: ${state?.level || 1} из ${LEVELS.length}.`)));
    }
  }

  function developerJumpToLevel(levelNumber) {
    if (!developerMode || !gameStarted || !state) return false;
    if (isPvpMode() || (networkMode === 'lan' && !networkIsHost)) { refreshDeveloperTools(); return false; }
    const target = clamp(Math.floor(Number(levelNumber) || 1), 1, LEVELS.length);
    state.paused = false;
    state.gameOver = false;
    state.victoryText = '';
    state.gameOverVisual = '';
    state.levelTransition = 0;
    state.nextLevel = 0;
    state.levelVictoryText = '';
    state.roundTransition = 0;
    for (const slot of getActivePlayerSlots()) {
      const maxKey = maxLivesKeyForSlot(slot);
      state[livesKeyForSlot(slot)] = Math.max(1, Number(state[maxKey]) || 2);
      state[respawnKeyForSlot(slot)] = false;
    }
    loadLevel(target);
    applyDeveloperImmortality();
    if (networkMode === 'lan' && networkIsHost) sendNetworkSnapshot(performance.now());
    if (developerStatusEl) developerStatusEl.textContent = `Загружена локация ${target}: ${LEVELS[target - 1].name}.`;
    canvas.focus();
    return true;
  }

  function developerJumpToBonusLevel(bonusKey) {
    if (!developerMode || !gameStarted || !state) return false;
    if (isPvpMode() || (networkMode === 'lan' && !networkIsHost)) { refreshDeveloperTools(); return false; }
    const bonus = BONUS_LEVELS.find(info => info.key === String(bonusKey || '')) || BONUS_LEVELS[0];
    const returnLevel = clamp(Math.floor(Number(state.level) || 1), 1, LEVELS.length);
    state.paused = false;
    state.gameOver = false;
    state.victoryText = '';
    state.gameOverVisual = '';
    state.levelTransition = 0;
    state.nextLevel = 0;
    state.levelVictoryText = '';
    state.roundTransition = 0;
    for (const slot of getActivePlayerSlots()) {
      const maxKey = maxLivesKeyForSlot(slot);
      state[livesKeyForSlot(slot)] = Math.max(1, Number(state[maxKey]) || 2);
      state[respawnKeyForSlot(slot)] = false;
    }
    state.devBonusTest = true;
    loadBonusLevel(bonus.key, returnLevel);
    applyDeveloperImmortality();
    if (networkMode === 'lan' && networkIsHost) sendNetworkSnapshot(performance.now());
    if (developerStatusEl) developerStatusEl.textContent = `DEV-тест: ${bonus.name}. Прогресс и награды не засчитываются.`;
    canvas.focus();
    return true;
  }

  function toggleDeveloperMode() {
    developerMode = !developerMode;
    developerBonusPoints = developerMode ? DEV_POINT_GRANT : 0;
    applyDeveloperImmortality();
    if (!developerMode && !isTankAvailable(selectedPlayerType)) {
      selectPlayerTank('standard');
    }
    if (networkMode === 'lan' && networkStarted && !networkIsHost) {
      sendNetwork({type:'dev_toggle', enabled:developerMode});
    }
    refreshTankPicker();
    populateLobbyTankSelect();
    refreshShop();
    updateHUD();
    refreshDeveloperTools();
    console.info(`Developer mode: ${developerMode ? 'ON' : 'OFF'}`);
  }

  function loadOwnedTanks() {
    ownedTanks = new Set(['standard']);
    try {
      const parsed = JSON.parse(localStorage.getItem(OWNED_TANKS_KEY) || '[]');
      if (Array.isArray(parsed)) parsed.forEach(key => { if (PLAYER_TYPES[key]) ownedTanks.add(key); });
    } catch (_) {}
  }

  function saveOwnedTanks() {
    try { localStorage.setItem(OWNED_TANKS_KEY, JSON.stringify([...ownedTanks])); } catch (_) {}
  }

  function loadCampaignProgress() {
    let firstCleared = false;
    let secondCleared = false;
    let thirdCleared = false;
    let fourthCleared = false;
    let savedRocketeerKills = 0;
    try {
      firstCleared = localStorage.getItem(FIRST_BOSS_CLEARED_KEY) === '1';
      secondCleared = localStorage.getItem(SECOND_BOSS_CLEARED_KEY) === '1';
      thirdCleared = localStorage.getItem(THIRD_BOSS_CLEARED_KEY) === '1';
      fourthCleared = localStorage.getItem(FOURTH_BOSS_CLEARED_KEY) === '1';
      const rows = JSON.parse(localStorage.getItem(LEADERBOARD_KEY) || '[]');
      if (Array.isArray(rows)) {
        if (!firstCleared) firstCleared = rows.some(row => Number(row?.level) >= FIRST_BOSS_LEVEL + 1);
        if (!secondCleared) secondCleared = rows.some(row => Number(row?.level) >= SECOND_BOSS_LEVEL + 1);
        if (!thirdCleared) thirdCleared = rows.some(row => Number(row?.level) >= THIRD_BOSS_LEVEL + 1);
        if (!fourthCleared) fourthCleared = rows.some(row => Number(row?.level) >= FOURTH_BOSS_LEVEL + 1);
      }
      if (fourthCleared) thirdCleared = true;
      if (thirdCleared) secondCleared = true;
      if (secondCleared) firstCleared = true;
      if (firstCleared) localStorage.setItem(FIRST_BOSS_CLEARED_KEY, '1');
      if (secondCleared) localStorage.setItem(SECOND_BOSS_CLEARED_KEY, '1');
      if (thirdCleared) localStorage.setItem(THIRD_BOSS_CLEARED_KEY, '1');
      if (fourthCleared) localStorage.setItem(FOURTH_BOSS_CLEARED_KEY, '1');
      savedRocketeerKills = clamp(Math.floor(Number(localStorage.getItem(ROCKETEER_KILLS_KEY)) || 0), 0, ROCKETEER_KILLS_TRACK_MAX);
    } catch (_) {}
    firstBossCleared = firstCleared;
    secondBossCleared = secondCleared;
    thirdBossCleared = thirdCleared;
    fourthBossCleared = fourthCleared;
    try { heartOfDesertCleared = localStorage.getItem(HEART_OF_DESERT_CLEARED_KEY)==='1'; } catch(_) { heartOfDesertCleared=false; }
    if (heartOfDesertCleared && !fourthBossCleared) {
      fourthBossCleared = true;
      try { localStorage.setItem(FOURTH_BOSS_CLEARED_KEY, '1'); } catch (_) {}
    }
    rocketeerKills = savedRocketeerKills;
  }

  function markFirstBossClearedLocal() {
    if (firstBossCleared) return;
    firstBossCleared = true;
    try { localStorage.setItem(FIRST_BOSS_CLEARED_KEY, '1'); } catch (_) {}
    refreshTankPicker();
    populateLobbyTankSelect();
    sendLocalProfileUpdate('first_special_progress');
    syncAchievements(gameStarted);
  }

  function markSecondBossClearedLocal() {
    if (secondBossCleared) return;
    secondBossCleared = true;
    firstBossCleared = true;
    try {
      localStorage.setItem(FIRST_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(SECOND_BOSS_CLEARED_KEY, '1');
    } catch (_) {}
    refreshTankPicker();
    populateLobbyTankSelect();
    sendLocalProfileUpdate('second_special_progress');
    syncAchievements(gameStarted);
  }

  function markThirdBossClearedLocal() {
    if (thirdBossCleared) return;
    thirdBossCleared = true;
    secondBossCleared = true;
    firstBossCleared = true;
    try {
      localStorage.setItem(FIRST_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(SECOND_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(THIRD_BOSS_CLEARED_KEY, '1');
    } catch (_) {}
    refreshTankPicker();
    populateLobbyTankSelect();
    sendLocalProfileUpdate('third_special_progress');
    syncAchievements(gameStarted);
  }

  function markFourthBossClearedLocal() {
    if (fourthBossCleared) return;
    fourthBossCleared = true;
    thirdBossCleared = true;
    secondBossCleared = true;
    firstBossCleared = true;
    try {
      localStorage.setItem(FIRST_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(SECOND_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(THIRD_BOSS_CLEARED_KEY, '1');
      localStorage.setItem(FOURTH_BOSS_CLEARED_KEY, '1');
    } catch (_) {}
    refreshTankPicker();
    populateLobbyTankSelect();
    sendLocalProfileUpdate('fourth_boss_progress');
    syncAchievements(gameStarted);
  }

  function setLocalRocketeerKills(value, notifyNetwork = false) {
    const next = clamp(Math.floor(Number(value) || 0), 0, ROCKETEER_KILLS_TRACK_MAX);
    if (next <= rocketeerKills) return false;
    rocketeerKills = next;
    try { localStorage.setItem(ROCKETEER_KILLS_KEY, String(rocketeerKills)); } catch (_) {}
    refreshTankPicker();
    populateLobbyTankSelect();
    if (notifyNetwork && networkMode === 'lan') sendLocalProfileUpdate('rocketeer_progress');
    return true;
  }

  function tankProgressRequirementMet(typeKey) {
    if (typeKey === 'duplet') return firstBossCleared;
    if (typeKey === 'sonicPlayer') return secondBossCleared;
    if (typeKey === 'artillery') return thirdBossCleared;
    if (typeKey === 'arrakisArtillery') return level33Cleared;
    if (typeKey === 'missile') return rocketeerKills >= ROCKETEER_KILLS_REQUIRED || isTankOwned(typeKey);
    if (typeKey === 'rocketBattery') return rocketeerKills >= ROCKET_BATTERY_KILLS_REQUIRED || isTankOwned(typeKey);
    if (typeKey === 'guidedLauncher') return rocketeerKills >= GUIDED_LAUNCHER_KILLS_REQUIRED || isTankOwned(typeKey);
    if (typeKey === 'sputnik') return Math.floor(Number(achievementStats?.campaignMaxLevelCleared) || 0) >= 45 || isTankOwned(typeKey);
    if (RESEARCH_LEVEL1_PLAYER_TYPES.has(typeKey)) return getResearchBlueprintCount(getLocalPlayerSlot()) >= 3 || isTankOwned(typeKey);
    if (RESEARCH_LEVEL2_PLAYER_TYPES.has(typeKey)) return getResearchBlueprintCount(getLocalPlayerSlot()) >= 5 || isTankOwned(typeKey);
    if (RESEARCH_LEVEL3_PLAYER_TYPES.has(typeKey)) return getResearchBlueprintCount(getLocalPlayerSlot()) >= 7 || isTankOwned(typeKey);
    if (typeKey === 'baneblade') return !!achievementState.technological_age || isTankOwned(typeKey);
    return true;
  }

  function tankUnlockRequirementText(typeKey) {
    if (typeKey === 'missile') return `Уничтожено ракетных танков: ${Math.min(ROCKETEER_KILLS_REQUIRED, rocketeerKills)}/${ROCKETEER_KILLS_REQUIRED}`;
    if (typeKey === 'rocketBattery') return `Уничтожено ракетных танков: ${Math.min(ROCKET_BATTERY_KILLS_REQUIRED, rocketeerKills)}/${ROCKET_BATTERY_KILLS_REQUIRED}`;
    if (typeKey === 'guidedLauncher') return `Уничтожено ракетных танков: ${Math.min(GUIDED_LAUNCHER_KILLS_REQUIRED, rocketeerKills)}/${GUIDED_LAUNCHER_KILLS_REQUIRED}`;
    if (typeKey === 'sputnik') return `Пройдено локаций кампании: ${Math.min(45, Math.floor(Number(achievementStats?.campaignMaxLevelCleared) || 0))}/45`;
    if (RESEARCH_LEVEL1_PLAYER_TYPES.has(typeKey)) return getLocalResearchLevel() < 1 ? 'Нужен Исследовательский центр уровня 1' : (isLocalStrategicBasePowered() ? 'Исследовательский чертёж недоступен' : 'Исследовательский центр обесточен · нужен энергобаланс > 0');
    if (RESEARCH_LEVEL2_PLAYER_TYPES.has(typeKey)) return getLocalResearchLevel() < 2 ? 'Нужен Исследовательский центр уровня 2' : (isLocalStrategicBasePowered() ? 'Нужен 5-й исследовательский чертёж' : 'Исследовательский центр обесточен · нужен энергобаланс > 0');
    if (RESEARCH_LEVEL3_PLAYER_TYPES.has(typeKey)) return getLocalResearchLevel() < 3 ? 'Нужен Исследовательский центр уровня 3' : (isLocalStrategicBasePowered() ? 'Нужен 7-й исследовательский чертёж' : 'Исследовательский центр обесточен · нужен энергобаланс > 0');
    if (typeKey === 'baneblade') { const owned = TECHNOLOGICAL_AGE_LEMAN_SET.filter(key => ownedTanks.has(key)).length; return `Ачивка «Технологический век»: ${owned}/${TECHNOLOGICAL_AGE_LEMAN_SET.length} Леман-Рассов`; }
    if (typeKey === 'duplet') return 'Сначала заверши 6-ю локацию';
    if (typeKey === 'sonicPlayer') return 'Сначала заверши 12-ю локацию';
    if (typeKey === 'artillery') return 'Сначала заверши 19-ю локацию';
    if (typeKey === 'arrakisArtillery') return 'Сначала заверши 33-ю локацию';
    return 'Условие не выполнено';
  }

  function grantTankOwnership(typeKey, autoSelect = false) {
    if (!PLAYER_TYPES[typeKey] || isTankOwned(typeKey)) return false;
    ownedTanks.add(typeKey);
    saveOwnedTanks();
    if (autoSelect) selectPlayerTank(typeKey);
    else {
      refreshTankPicker();
      populateLobbyTankSelect();
    }
    syncAchievements(gameStarted);
    return true;
  }

  function loadShopProgress() {
    try {
      purchasedLifeUpgrades = clamp(Math.floor(Number(localStorage.getItem(LIFE_UPGRADES_KEY)) || 0), 0, LIFE_UPGRADE_PRICES.length);
      purchasedBaseUpgrades = clamp(Math.floor(Number(localStorage.getItem(BASE_UPGRADES_KEY)) || 0), 0, BASE_UPGRADE_PRICES.length);
    } catch (_) {
      purchasedLifeUpgrades = 0;
      purchasedBaseUpgrades = 0;
    }
  }

  function saveShopProgress() {
    try {
      localStorage.setItem(LIFE_UPGRADES_KEY, String(purchasedLifeUpgrades));
      localStorage.setItem(BASE_UPGRADES_KEY, String(purchasedBaseUpgrades));
    } catch (_) {}
  }

  function getMaxLives() {
    return BASE_STARTING_LIVES + purchasedLifeUpgrades;
  }

  function getLocalBaseMaxHp() {
    return BASE_STARTING_HP + purchasedBaseUpgrades;
  }

  function getMatchBaseUpgradeCount() {
    if (networkMode !== 'lan') return purchasedBaseUpgrades;
    const sharedBest = networkPlayers.reduce((best, info) => Math.max(best, Number(info?.baseUpgrades) || 0), 0);
    return clamp(Math.max(sharedBest, networkIsHost ? purchasedBaseUpgrades : 0), 0, BASE_UPGRADE_PRICES.length);
  }

  function getMatchBaseMaxHp() {
    return BASE_STARTING_HP + getMatchBaseUpgradeCount();
  }

  function isTankOwned(typeKey) {
    return ownedTanks.has(typeKey);
  }

  function isTankAvailable(typeKey) {
    if (!PLAYER_TYPES[typeKey]) return false;
    if (SECRET_BOSS_PLAYER_TYPES.has(typeKey)) return developerMode || isTankOwned(typeKey);
    if (developerMode) return true;
    if (typeKey === 'duplet' && !firstBossCleared) return false;
    if (typeKey === 'sonicPlayer' && !secondBossCleared) return false;
    if (typeKey === 'artillery' && !thirdBossCleared) return false;
    if (typeKey === 'arrakisArtillery' && !level33Cleared) return false;
    if (typeKey === 'baneblade' && !achievementState.technological_age) return false;
    return isTankOwned(typeKey);
  }

  const PURCHASABLE_ACHIEVEMENT_TANKS = Object.freeze(Object.keys(TANK_PRICES).filter(key => key !== 'standard' && !RESEARCH_PLAYER_TYPES.has(key)));
  const LUCKY_CASE_TANKS = Object.freeze(['ordos','harkonnen','atreides','imperial']);
  const MAD_ENGINEER_TANKS = Object.freeze(['nuclearArtillery','guidedLauncher','sputnik']);
  const MAD_ENGINEER_LEMAN_VARIANTS = Object.freeze(['lemanRuss','lemanRussLongCannon','lemanRussSniper','lemanRussTitan','lemanRussHyperion','lemanRussPlasma','lemanRussMars','lemanRussMinigun']);
  const TECHNOLOGICAL_AGE_LEMAN_SET = Object.freeze(['lemanRuss','lemanRussLongCannon','lemanRussSniper','lemanRussTitan','lemanRussHyperion','lemanRussPlasma','lemanRussMars','lemanRussMinigun']);

  function defaultCareerStats() {
    return {
      schema:2, firstTrackedAt:Date.now(), battleSeconds:0,
      matchesStarted:0, campaignMatches:0, lanMatches:0, pvpMatches:0,
      campaignVictories:0, campaignDefeats:0, pvpVictories:0, pvpDefeats:0, pvpRoundsWon:0,
      kills:0, pvpKills:0, bossKills:0, campaignBossKills:0, bonusBossKills:0, deaths:0,
      shotsFired:0, damageDealt:0, damageTaken:0,
      levelsCleared:0, bonusLevelsCleared:0,
      portalsEntered:0, regularPortalsEntered:0, ultroPortalsEntered:0,
      pointsEarned:0, pointsSpent:0,
      casesEarned:0, casesPurchased:0, tanksPurchased:0, upgradesPurchased:0, promosRedeemed:0,
      bestMatchScore:0, tankDeployments:{}, mapStats:{}, lastUpdatedAt:Date.now()
    };
  }
  function normalizeCareerStats(raw) {
    const base=defaultCareerStats(), src=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
    const next={...base,...src};
    for(const key of Object.keys(base)){
      if(typeof base[key]==='number') next[key]=Math.max(0,Number(next[key])||0);
    }
    next.firstTrackedAt=Math.max(0,Math.floor(Number(src.firstTrackedAt)||Date.now()));
    next.lastUpdatedAt=Math.max(0,Math.floor(Number(src.lastUpdatedAt)||Date.now()));
    const deployments=src.tankDeployments&&typeof src.tankDeployments==='object'&&!Array.isArray(src.tankDeployments)?src.tankDeployments:{};
    next.tankDeployments={};
    for(const [key,value] of Object.entries(deployments)) if(PLAYER_TYPES[key]) next.tankDeployments[key]=Math.max(0,Math.floor(Number(value)||0));
    const maps=src.mapStats&&typeof src.mapStats==='object'&&!Array.isArray(src.mapStats)?src.mapStats:{};
    next.mapStats={};
    for(const [mapKey,value] of Object.entries(maps)){
      if(!/^(campaign:\d{1,3}|bonus:[a-zA-Z0-9_-]{1,40}|pvp:\d{1,3})$/.test(mapKey)||!value||typeof value!=='object'||Array.isArray(value))continue;
      next.mapStats[mapKey]={kills:Math.max(0,Math.floor(Number(value.kills)||0)),points:Math.max(0,Math.floor(Number(value.points)||0))};
    }
    next.schema=2;
    return next;
  }
  function loadCareerStats() {
    try { careerStats=normalizeCareerStats(JSON.parse(localStorage.getItem(CAREER_STATS_KEY)||'{}')); }
    catch(_) { careerStats=defaultCareerStats(); }
    // Safe migration: old versions did not retain lifetime economy/combat totals.
    // Only facts that still exist in the save are restored; missing history is never invented.
    careerStats.pointsEarned=Math.max(Number(careerStats.pointsEarned)||0,Math.max(0,Number(careerPoints)||0));
    careerStats.bestMatchScore=Math.max(Number(careerStats.bestMatchScore)||0,getLeaderboard().reduce((best,row)=>Math.max(best,Number(row?.score)||0),0));
    saveCareerStats();
  }
  function saveCareerStats() {
    if(!careerStats||typeof careerStats!=='object') return;
    careerStats.lastUpdatedAt=Date.now();
    try { localStorage.setItem(CAREER_STATS_KEY,JSON.stringify(careerStats)); } catch(_) {}
  }
  function careerStatAdd(key,amount=1,save=true) {
    if(!careerStats||!Object.prototype.hasOwnProperty.call(defaultCareerStats(),key)) return;
    const value=Number(amount)||0;
    if(!value)return;
    careerStats[key]=Math.max(0,(Number(careerStats[key])||0)+value);
    if(save) saveCareerStats();
  }
  function careerStatMax(key,value,save=true) {
    if(!careerStats||!Object.prototype.hasOwnProperty.call(defaultCareerStats(),key)) return;
    careerStats[key]=Math.max(Number(careerStats[key])||0,Number(value)||0);
    if(save) saveCareerStats();
  }
  function recordCareerStatForSlot(slot,key,amount=1) {
    const target=normalizePlayerSlot(slot||1);
    const local=getLocalPlayerSlot();
    if(networkMode!=='lan'||target===local){ careerStatAdd(key,amount); return; }
    if(networkIsHost&&[2,3].includes(target)){
      const value=Number(amount)||0;if(!value)return;
      networkCareerStatsPending[target]=networkCareerStatsPending[target]||{};
      networkCareerStatsPending[target][key]=(Number(networkCareerStatsPending[target][key])||0)+value;
    }
  }
  function recordCareerMaxForSlot(slot,key,value) {
    const target=normalizePlayerSlot(slot||1);
    const local=getLocalPlayerSlot();
    if(networkMode!=='lan'||target===local){ careerStatMax(key,value); return; }
    if(networkIsHost&&networkSocket?.readyState===WebSocket.OPEN) sendNetwork({type:'career_stat_event',targetSlot:target,key,value:Number(value)||0,mode:'max'});
  }
  function careerMapDescriptorByKey(mapKey) {
    const key=String(mapKey||'');
    let match=key.match(/^campaign:(\d+)$/);
    if(match){ const index=clamp(Math.floor(Number(match[1])||1),1,LEVELS.length)-1,info=LEVELS[index]; return info?{key:`campaign:${index+1}`,name:info.name,short:info.short||info.name,theme:info.theme||'campaign',floor:info.floor,grid:info.grid,mode:'campaign',index}:null; }
    match=key.match(/^bonus:([a-zA-Z0-9_-]+)$/);
    if(match){ const info=BONUS_LEVELS.find(item=>item.key===match[1]); return info?{key:`bonus:${info.key}`,name:info.name,short:info.short||info.name,theme:info.theme||'bonus',floor:info.floor,grid:info.grid,mode:'bonus',index:BONUS_LEVELS.indexOf(info)}:null; }
    match=key.match(/^pvp:(\d+)$/);
    if(match){ const index=clamp(Math.floor(Number(match[1])||0),0,PVP_LEVELS.length-1),info=PVP_LEVELS[index]; return info?{key:`pvp:${index}`,name:info.name,short:info.short||info.name,theme:info.theme||'pvp',floor:info.floor,grid:info.grid,mode:'pvp',index}:null; }
    return null;
  }
  function getCurrentCareerMapDescriptor() {
    if(!state)return null;
    if(isPvpMode())return careerMapDescriptorByKey(`pvp:${Math.max(0,Math.floor(Number(state.pvpMapIndex)||0))}`);
    if(state.inBonusLevel&&state.bonusLevelKey)return careerMapDescriptorByKey(`bonus:${state.bonusLevelKey}`);
    return careerMapDescriptorByKey(`campaign:${clamp(Math.floor(Number(state.level)||1),1,LEVELS.length)}`);
  }
  function careerMapStatAdd(mapKey,field,amount=1,save=true) {
    const descriptor=careerMapDescriptorByKey(mapKey),value=Math.max(0,Math.floor(Number(amount)||0));
    if(!descriptor||!value||!['kills','points'].includes(field))return;
    careerStats.mapStats=careerStats.mapStats&&typeof careerStats.mapStats==='object'?careerStats.mapStats:{};
    const row=careerStats.mapStats[descriptor.key]&&typeof careerStats.mapStats[descriptor.key]==='object'?careerStats.mapStats[descriptor.key]:{kills:0,points:0};
    row.kills=Math.max(0,Math.floor(Number(row.kills)||0)); row.points=Math.max(0,Math.floor(Number(row.points)||0)); row[field]+=value; careerStats.mapStats[descriptor.key]=row;
    if(save)saveCareerStats();
  }
  function recordCareerMapStatForSlot(slot,field,amount=1,mapKey='') {
    const descriptor=mapKey?careerMapDescriptorByKey(mapKey):getCurrentCareerMapDescriptor(); if(!descriptor)return;
    const target=normalizePlayerSlot(slot||1),local=getLocalPlayerSlot(),value=Math.max(0,Math.floor(Number(amount)||0)); if(!value)return;
    if(networkMode!=='lan'||target===local){careerMapStatAdd(descriptor.key,field,value);return;}
    if(networkIsHost&&[2,3].includes(target)){ networkCareerMapStatsPending[target]=networkCareerMapStatsPending[target]||{}; const row=networkCareerMapStatsPending[target][descriptor.key]||{kills:0,points:0}; row[field]=Math.max(0,Math.floor(Number(row[field])||0)+value); networkCareerMapStatsPending[target][descriptor.key]=row; }
  }
  function drawStatisticsMapPreview(canvas,mapKey) {
    if(!(canvas instanceof HTMLCanvasElement))return; const info=careerMapDescriptorByKey(mapKey)||careerMapDescriptorByKey('campaign:1'); if(!info)return;
    const ctx=canvas.getContext('2d'); if(!ctx)return; const w=canvas.width,h=canvas.height; ctx.clearRect(0,0,w,h); ctx.fillStyle=info.floor||'#182028';ctx.fillRect(0,0,w,h);
    const shade=ctx.createLinearGradient(0,0,w,h);shade.addColorStop(0,'rgba(255,255,255,.055)');shade.addColorStop(.48,'rgba(255,255,255,0)');shade.addColorStop(1,'rgba(0,0,0,.30)');ctx.fillStyle=shade;ctx.fillRect(0,0,w,h);
    ctx.strokeStyle=info.grid||'rgba(255,255,255,.05)';ctx.lineWidth=1;for(let x=0;x<w;x+=18){ctx.beginPath();ctx.moveTo(x+.5,0);ctx.lineTo(x+.5,h);ctx.stroke();}for(let y=0;y<h;y+=18){ctx.beginPath();ctx.moveTo(0,y+.5);ctx.lineTo(w,y+.5);ctx.stroke();}
    let seed=0;for(const ch of info.key)seed=(seed*33+ch.charCodeAt(0))>>>0;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const theme=String(info.theme||'');
    if(/water|flood|marine|coastal/i.test(theme)){ctx.fillStyle='rgba(83,181,211,.14)';for(let i=0;i<3;i++)ctx.fillRect(0,16+i*26,w,8);}else if(/desert|sand/i.test(theme)){ctx.fillStyle='rgba(255,220,145,.08)';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(rnd()*w,rnd()*h,8+rnd()*18,0,Math.PI*2);ctx.fill();}}else if(/snow|frost|polar|highmountain/i.test(theme)){ctx.fillStyle='rgba(238,251,255,.13)';for(let i=0;i<7;i++)ctx.fillRect(rnd()*w,rnd()*h,10+rnd()*20,3+rnd()*5);}else if(/lava|slag|foundry|ash/i.test(theme)){ctx.strokeStyle='rgba(255,130,70,.22)';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(rnd()*w,rnd()*h);ctx.lineTo(rnd()*w,rnd()*h);ctx.lineTo(rnd()*w,rnd()*h);ctx.stroke();}}
    for(let i=0;i<9;i++){const rw=12+Math.floor(rnd()*22),rh=8+Math.floor(rnd()*16),x=5+Math.floor(rnd()*Math.max(1,w-rw-10)),y=5+Math.floor(rnd()*Math.max(1,h-rh-10));ctx.fillStyle='rgba(5,10,14,.40)';ctx.fillRect(x,y,rw,rh);ctx.strokeStyle='rgba(225,243,249,.10)';ctx.strokeRect(x+.5,y+.5,rw-1,rh-1);}
    ctx.fillStyle='rgba(126,226,255,.86)';ctx.beginPath();ctx.arc(w*.18,h*.78,3.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(255,197,92,.92)';ctx.beginPath();ctx.arc(w*.82,h*.22,3.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.18)';ctx.strokeRect(.5,.5,w-1,h-1);
  }
  function recordMatchStart() {
    if(!gameStarted)return;
    careerStatAdd('matchesStarted',1,false);
    if(isPvpMode()) careerStatAdd('pvpMatches',1,false); else careerStatAdd('campaignMatches',1,false);
    if(networkMode==='lan') careerStatAdd('lanMatches',1,false);
    const tank=String(selectedPlayerType||'standard');
    careerStats.tankDeployments=careerStats.tankDeployments&&typeof careerStats.tankDeployments==='object'?careerStats.tankDeployments:{};
    careerStats.tankDeployments[tank]=Math.max(0,Math.floor(Number(careerStats.tankDeployments[tank])||0))+1;
    saveCareerStats();
  }
  function recordMatchResultForAllPlayers() {
    if(!state)return;
    const slots=getActivePlayerSlots();
    if(isPvpMode()){
      const winner=slots.reduce((best,slot)=>Number(state[pvpWinsKeyForSlot(slot)]||0)>Number(state[pvpWinsKeyForSlot(best)]||0)?slot:best,slots[0]||1);
      for(const slot of slots){
        recordCareerStatForSlot(slot,slot===winner?'pvpVictories':'pvpDefeats',1);
        recordCareerMaxForSlot(slot,'bestMatchScore',Number(state[scoreKeyForSlot(slot)]||0));
      }
    }else{
      const resultText=String(state.victoryText||'');
      const defeat=/БАЗА УНИЧТОЖЕНА|ОТРЯД УНИЧТОЖЕН|ТАНК УНИЧТОЖЕН/i.test(resultText);
      const victory=!defeat&&/ПРОЙДЕН[АЫО]?|ПОБЕДИЛ|BASTION PRIME УНИЧТОЖЕН/i.test(resultText);
      for(const slot of slots){
        recordCareerStatForSlot(slot,victory?'campaignVictories':'campaignDefeats',1);
        recordCareerMaxForSlot(slot,'bestMatchScore',Number(state[scoreKeyForSlot(slot)]||0));
      }
    }
  }
  function formatCareerDuration(seconds) {
    const total=Math.max(0,Math.floor(Number(seconds)||0)), hours=Math.floor(total/3600), minutes=Math.floor((total%3600)/60);
    if(hours>0)return currentLanguage==='en'?`${hours} h ${minutes} m`:`${hours} ч ${minutes} мин`;
    return currentLanguage==='en'?`${minutes} min`:`${minutes} мин`;
  }
  function statisticsNumber(value){ return Math.max(0,Math.floor(Number(value)||0)).toLocaleString(currentLanguage==='en'?'en-US':'ru-RU'); }
  function statisticsRatio(a,b){ const den=Math.max(0,Number(b)||0); return den>0?(Math.max(0,Number(a)||0)/den).toFixed(2):statisticsNumber(a); }
  function isStatisticsModalOpen() {
    return !!statisticsModalEl && !statisticsModalEl.classList.contains('hidden');
  }
  function setStatisticsPauseForSlot(slot, active) {
    if (!gameStarted || !state || state.gameOver) return;
    const holder = normalizePlayerSlot(slot || 1);
    if (active) {
      if (!statisticsPauseHolders.size) statisticsPauseBaseState = !!state.paused;
      statisticsPauseHolders.add(holder);
      state.paused = true;
    } else {
      statisticsPauseHolders.delete(holder);
      if (!statisticsPauseHolders.size) state.paused = !!statisticsPauseBaseState;
    }
    if (networkMode === 'lan' && networkIsHost) sendNetworkSnapshot(performance.now());
  }
  function acquireStatisticsPause() {
    if (!gameStarted || !state || state.gameOver) return;
    if (networkMode === 'lan' && !networkIsHost) {
      sendNetwork({type:'statistics_pause',active:true});
      return;
    }
    setStatisticsPauseForSlot(networkMode === 'lan' ? (networkSlot || 1) : 1, true);
  }
  function releaseStatisticsPause() {
    if (networkMode === 'lan' && !networkIsHost) {
      if (networkStarted) sendNetwork({type:'statistics_pause',active:false});
      return;
    }
    setStatisticsPauseForSlot(networkMode === 'lan' ? (networkSlot || 1) : 1, false);
  }
  function openStatisticsModal() {
    if(!statisticsModalEl)return;
    if (isStatisticsModalOpen()) { renderStatistics(); return; }
    acquireStatisticsPause();
    renderStatistics();
    statisticsModalEl.classList.remove('hidden');
    statisticsModalEl.setAttribute('aria-hidden','false');
    statisticsCloseBtn?.focus?.({preventScroll:true});
  }
  function closeStatisticsModal() {
    if(!statisticsModalEl || !isStatisticsModalOpen())return;
    statisticsModalEl.classList.add('hidden');
    statisticsModalEl.setAttribute('aria-hidden','true');
    releaseStatisticsPause();
    canvas?.focus?.();
  }
