    const deployments=Object.entries(careerStats.tankDeployments||{}).filter(([key])=>PLAYER_TYPES[key]).sort((a,b)=>Number(b[1])-Number(a[1]));
    const favKey=deployments[0]?.[0]||selectedPlayerType||'standard';
