      // Три вида промышленных цистерн. Зелёные цистерны около центра разнесены к краям:
      // верхняя пара освобождает выезд WARHEAD, нижняя — прямой сектор атаки базы игрока.
      [[3,14],[4,14],[21,14],[22,14],[4,12],[5,12]].forEach(p => stamp(grid,9,...p));
