      [[7,3,1,4],[18,3,1,4],[6,10,2,1],[18,10,2,1],[10,13,2,2],[14,13,2,2]].forEach(r => stamp(grid,2,...r));
      [[4,3],[21,3],[5,13],[20,13]].forEach(p => stamp(grid,9,...p));
