      [[3,7,2,2],[8,7,2,2],[13,7,2,2],[18,7,2,2],[23,7,2,2]].forEach(r => stamp(grid,6,...r));
      [[7,3,4,2],[15,3,4,2],[9,12,8,2]].forEach(r => stamp(grid,8,...r));
      [[1,10,5,2],[20,10,5,2]].forEach(r => stamp(grid,7,...r));
      [[3,4,4,1],[19,4,4,1],[4,12,3,1],[19,12,3,1],[6,16,3,1],[17,16,3,1]].forEach(r => stamp(grid,1,...r));
      [[6,2,1,4],[19,2,1,4],[7,10,1,4],[18,10,1,4],[11,4,4,1],[11,15,4,1]].forEach(r => stamp(grid,2,...r));
      [[4,3],[21,3],[5,13]].forEach(p => stamp(grid,9,...p));
      [[9,5],[16,5],[20,13]].forEach(p => stamp(grid,10,...p));
      [[12,10],[13,10],[18,15]].forEach(p => stamp(grid,11,...p));
