  function respawnKeyForSlot(slot) { return `respawnPending${normalizePlayerSlot(slot)}`; }
  function devKeyForSlot(slot) { return `devImmortal${normalizePlayerSlot(slot)}`; }
  function pvpWinsKeyForSlot(slot) { return `pvpWins${normalizePlayerSlot(slot)}`; }
  function firstBossClearKeyForSlot(slot) { return `firstBossCleared${normalizePlayerSlot(slot)}`; }
  function secondBossClearKeyForSlot(slot) { return `secondBossCleared${normalizePlayerSlot(slot)}`; }
  function ultroMeteorHitKeyForSlot(slot) { return `ultroMeteorHit${normalizePlayerSlot(slot)}`; }
  function ultroBlackHoleKilledKeyForSlot(slot) { return `ultroBlackHoleKilled${normalizePlayerSlot(slot)}`; }
  function ultro2GalaxyEndHitKeyForSlot(slot) { return `ultro2GalaxyEndHit${normalizePlayerSlot(slot)}`; }
  function ultro2DivineBeamHitKeyForSlot(slot) { return `ultro2DivineBeamHit${normalizePlayerSlot(slot)}`; }
  function ultroMeteorKilledKeyForSlot(slot) { return `ultroMeteorKilled${normalizePlayerSlot(slot)}`; }
  function ultro2GalaxyEndKilledKeyForSlot(slot) { return `ultro2GalaxyEndKilled${normalizePlayerSlot(slot)}`; }
  function ultro2DivineBeamKilledKeyForSlot(slot) { return `ultro2DivineBeamKilled${normalizePlayerSlot(slot)}`; }
  function ultro3WorldRiftKilledKeyForSlot(slot) { return `ultro3WorldRiftKilled${normalizePlayerSlot(slot)}`; }
  function ultro3PlanetKilledKeyForSlot(slot) { return `ultro3PlanetKilled${normalizePlayerSlot(slot)}`; }
  function ultro3CrownKilledKeyForSlot(slot) { return `ultro3CrownKilled${normalizePlayerSlot(slot)}`; }
  function ultro3RealityKilledKeyForSlot(slot) { return `ultro3RealityKilled${normalizePlayerSlot(slot)}`; }
  function ultro3WorldRiftSurvivedKeyForSlot(slot) { return `ultro3WorldRiftSurvived${normalizePlayerSlot(slot)}`; }
  function ultro3PlanetSurvivedKeyForSlot(slot) { return `ultro3PlanetSurvived${normalizePlayerSlot(slot)}`; }
  function classicStandardEligibleKeyForSlot(slot) { return `classicStandardEligible${normalizePlayerSlot(slot)}`; }
  function level33ClearKeyForSlot(slot) { return `level33Cleared${normalizePlayerSlot(slot)}`; }
  function markLevel33ClearedLocal(){ if(level33Cleared)return; level33Cleared=true; try{localStorage.setItem(LEVEL33_CLEARED_KEY,'1');}catch(_){} refreshTankPicker();populateLobbyTankSelect(); if(networkMode==='lan')sendLocalProfileUpdate('level33_progress'); }

  function thirdBossClearKeyForSlot(slot) { return `thirdBossCleared${normalizePlayerSlot(slot)}`; }
  function fourthBossClearKeyForSlot(slot) { return `fourthBossCleared${normalizePlayerSlot(slot)}`; }
  function rocketeerKillsKeyForSlot(slot) { return `rocketeerKills${normalizePlayerSlot(slot)}`; }
