            if (bonusKey === SECRET_BONUS_LEVEL_KEY) {
              if (!!state.ultroReachedPhase5 && !state[ultroBlackHoleKilledKeyForSlot(slot)]) achievementStats.ultroNoBlackHoleDeathWin = true;
              if (!state[ultroMeteorKilledKeyForSlot(slot)]) achievementStats.ultroNoMeteorWin = true;
            }
