      for(let i=0;i<18;i++){const a=Math.atan2(d.y,d.x)+(Math.random()-.5)*0.98,s=30+Math.random()*70,max=.16+Math.random()*.18;state.particles.push({type:'spark',x:mx,y:my,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:max,max,size:1.9+Math.random()*2.7,hyperionFx:true});}
