      for(let i=0;i<5;i++){const max=.34+Math.random()*.20;state.particles.push({type:'smoke',x:mx+(Math.random()-.5)*6,y:my+(Math.random()-.5)*6,vx:(Math.random()-.5)*18-d.x*(10+Math.random()*14),vy:(Math.random()-.5)*18-d.y*(10+Math.random()*14),life:max,max,size:5.5+Math.random()*4.2,marsPlayerTrailSmoke:true});}
