    for(let combatSfxI=combatSfxBulletStart;combatSfxI<state.bullets.length;combatSfxI++){const combatSfxBullet=state.bullets[combatSfxI];if(combatSfxBullet&&!combatSfxBullet._sfxSource)combatSfxBullet._sfxSource=rawVariantKey;}

    if (t.team === 'player') {
      const [minDelay, maxDelay] = t.fireDelay;
      t.fireCooldown = minDelay + Math.random() * (maxDelay - minDelay);
    } else {
      const [minDelay, maxDelay] = t.fireDelay;
      t.fireCooldown = minDelay + Math.random() * (maxDelay - minDelay);
    }
    if(t.team==='player'&&variantKey==='researchCitadel')t.fireCooldown=t.citadelDeployed?2.65:.92;
    if(t.team==='player'&&variantKey==='chimera'){const mode=Math.abs(Math.floor(Number(t.chimeraMode||0)))%3;t.fireCooldown=mode===0?.48:(mode===1?1.18:.72);}
    t.flash = 0.08;
