  function addExplosion(x, y, strength = 1) {
    for (let i = 0; i < 9 * strength; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = (30 + Math.random()*90) * strength;
      state.particles.push({type: 'spark', x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s, life: .25 + Math.random()*.35, max: .6, size: 2 + Math.random()*4});
    }
    state.shake = Math.max(state.shake, 4 * strength);
  }

  function destroySplashBricks(x, y, splashRadius) {
    if (!state?.map) return 0;
    const radius = Math.max(0, Number(splashRadius) || 0);
    if (radius <= 0) return 0;
    const radius2 = radius * radius;
    const minX = clamp(Math.floor((x - radius) / TILE), 0, COLS - 1);
    const maxX = clamp(Math.floor((x + radius) / TILE), 0, COLS - 1);
    const minY = clamp(Math.floor((y - radius) / TILE), 0, ROWS - 1);
    const maxY = clamp(Math.floor((y + radius) / TILE), 0, ROWS - 1);
    let destroyed = 0;

    for (let ty = minY; ty <= maxY; ty++) {
      for (let tx = minX; tx <= maxX; tx++) {
        // Обычный кирпич (1) и пустынная кладка (15) — одинаково разрушаемые блоки.
        // Сталь, база, вода, лава и промышленные цистерны сплэшем не повреждаются.
        if (state.map[ty][tx] !== 1 && state.map[ty][tx] !== 15) continue;
        const cx = tx * TILE + TILE / 2;
        const cy = ty * TILE + TILE / 2;
        const dx = cx - x;
        const dy = cy - y;
        if (dx * dx + dy * dy > radius2) continue;
        state.map[ty][tx] = 0;
        destroyed++;
        addExplosion(cx, cy, .18);
      }
    }
    return destroyed;
  }

  function projectileHasSplash(b) {
    if (!b) return false;
    return b.kind === 'rocketMissile' || b.kind === 'artilleryShell' || Number(b.splashRadius) > 0;
  }

  function addRocketImpact(x, y, sourceTeam = 'enemy', sourceSlot = 0, excludedTank = null, splashRadius = 52, splashDamage = 1, bypassInvuln = false) {
    splashRadius = Math.max(24, Number(splashRadius) || 52);
    splashDamage = Math.max(1, Math.floor(Number(splashDamage) || 1));

    addExplosion(x, y, .72);
    for (let i = 0; i < 5; i++) {
      const max = .42 + Math.random() * .24;
      state.particles.push({
        type: 'smoke',
        x: x + (Math.random() - .5) * 8,
        y: y + (Math.random() - .5) * 8,
        vx: (Math.random() - .5) * 24,
        vy: -10 - Math.random() * 18,
        life: max, max,
        size: 4 + Math.random() * 4
      });
    }
    for (let i = 0; i < 4; i++) {
      const max = .18 + Math.random() * .16;
      state.particles.push({
        type: 'flame',
        x: x + (Math.random() - .5) * 6,
        y: y + (Math.random() - .5) * 6,
        vx: (Math.random() - .5) * 30,
        vy: -18 - Math.random() * 22,
        life: max, max,
        size: 3 + Math.random() * 3,
        intensity: .9
      });
    }

    // Дымное кольцо ударной волны показывает реальный радиус сплэша.
    state.particles.push({
      type: 'shockwave', x, y, vx: 0, vy: 0,
      life: .38, max: .38, size: 10, maxSize: splashRadius, thickness: Math.max(10, splashRadius * .18)
    });

    // Сплэш действует и на танки, и на все центры разрушаемых кирпичных
    // блоков, попавшие внутрь радиуса. Прямо поражённый танк исключается,
    // потому что прямой урон снаряда уже был применён отдельно.
    destroySplashBricks(x, y, splashRadius);

    const splashRadius2 = splashRadius * splashRadius;
    const targets = getAllPlayerTanks().filter(t => t && t.alive && t !== excludedTank);
    for (const target of targets) {
      const slot = target.playerSlot || 1;
      const canHit = sourceTeam !== 'player' || (isPvpMode() && sourceSlot && sourceSlot !== slot);
      if (!canHit) continue;
      const cx = target.x + target.w / 2;
      const cy = target.y + target.h / 2;
      const dx = cx - x;
      const dy = cy - y;
      if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
    }
    if (sourceTeam === 'player') {
      for (const target of state.enemies || []) {
        if (!target?.alive || target === excludedTank) continue;
        const cx = target.x + target.w / 2;
        const cy = target.y + target.h / 2;
        const dx = cx - x;
        const dy = cy - y;
        if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
      }
    }
    state.shake = Math.max(state.shake, 3.6);
  }


  function addBallistaWaveImpact(x, y, sourceTeam = 'enemy', sourceSlot = 0, excludedTank = null, splashRadius = 200, splashDamage = 5, bypassInvuln = false) {
    splashRadius = Math.max(56, Number(splashRadius) || 200);
    splashDamage = Math.max(1, Math.floor(Number(splashDamage) || 1));

    state.particles.push({type:'shockwave',x,y,vx:0,vy:0,life:.58,max:.58,size:18,maxSize:Math.max(110, splashRadius * .72),thickness:24,plasmaFx:true});
    state.particles.push({type:'shockwave',x,y,vx:0,vy:0,life:.82,max:.82,size:26,maxSize:splashRadius + 26,thickness:30,hyperionFx:true});
    state.particles.push({type:'shockwave',x,y,vx:0,vy:0,life:.98,max:.98,size:34,maxSize:splashRadius + 78,thickness:18,plasmaFx:true});

    for (let i = 0; i < 34; i++) {
      const aa = Math.random() * Math.PI * 2;
      const sp = 46 + Math.random() * 165;
      const life = .24 + Math.random() * .30;
      state.particles.push({
        type:'spark',x:x + (Math.random() - .5) * 10,y:y + (Math.random() - .5) * 10,
        vx:Math.cos(aa) * sp,vy:Math.sin(aa) * sp,
        life,max:life,size:2.2 + Math.random() * 3.2,
        hyperionFx:true,thunderFx:true
      });
    }

    for (let i = 0; i < 18; i++) {
      const life = .64 + Math.random() * .36;
      state.particles.push({
        type:'smoke',
        x:x + (Math.random() - .5) * 20,
        y:y + 6 + Math.random() * 18,
        vx:(Math.random() - .5) * 26,
        vy:-58 - Math.random() * 48,
        life,max:life,size:10 + Math.random() * 7,
        plasmaFx:true
      });
    }
    for (let i = 0; i < 28; i++) {
      const aa = Math.PI + Math.random() * Math.PI;
      const sp = 18 + Math.random() * 72;
      const life = .78 + Math.random() * .46;
      state.particles.push({
        type:'smoke',
        x:x + (Math.random() - .5) * 14,
        y:y - 10 - Math.random() * 18,
        vx:Math.cos(aa) * sp * .78,
        vy:Math.sin(aa) * sp * .42 - 26 - Math.random() * 18,
        life,max:life,size:12 + Math.random() * 10,
        hyperionTrailSmoke:true
      });
    }
    for (let i = 0; i < 14; i++) {
      const side = i % 2 === 0 ? -1 : 1;
      const life = .58 + Math.random() * .30;
      state.particles.push({
        type:'smoke',
        x:x + side * (10 + Math.random() * 20),
        y:y - 4 - Math.random() * 10,
        vx:side * (26 + Math.random() * 38),
        vy:-16 - Math.random() * 26,
        life,max:life,size:8 + Math.random() * 6,
        plasmaFx:true
      });
    }

    destroySplashBricks(x, y, splashRadius);
    const splashRadius2 = splashRadius * splashRadius;
    const targets = getAllPlayerTanks().filter(t => t && t.alive && t !== excludedTank);
    for (const target of targets) {
      const slot = target.playerSlot || 1;
      const canHit = sourceTeam !== 'player' || (isPvpMode() && sourceSlot && sourceSlot !== slot);
      if (!canHit) continue;
      const cx = target.x + target.w / 2;
      const cy = target.y + target.h / 2;
      const dx = cx - x;
      const dy = cy - y;
      if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
    }
    if (sourceTeam === 'player') {
      for (const target of state.enemies || []) {
        if (!target?.alive || target === excludedTank) continue;
        const cx = target.x + target.w / 2;
        const cy = target.y + target.h / 2;
        const dx = cx - x;
        const dy = cy - y;
        if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
      }
    }
    state.shake = Math.max(state.shake, 10.5);
  }

  function addCrystalImpact(x, y, sourceTeam = 'enemy', sourceSlot = 0, excludedTank = null, splashRadius = 44, splashDamage = 1, bypassInvuln = false, mode = 'shard') {
    splashRadius = Math.max(20, Number(splashRadius) || 44);
    splashDamage = Math.max(1, Math.floor(Number(splashDamage) || 1));
    const coreMode = mode === 'core';
    const missileMode = mode === 'missile';
    const laserMode = mode === 'laser';

    if (!laserMode) {
      state.particles.push({type:'shockwave',x,y,vx:0,vy:0,life:coreMode?.55:.34,max:coreMode?.55:.34,size:coreMode?12:7,maxSize:splashRadius,thickness:coreMode?14:8,crystalFx:true});
    }
    const sparkCount = coreMode ? 26 : (laserMode ? 10 : (missileMode ? 14 : 12));
    for (let i = 0; i < sparkCount; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = (coreMode ? 55 : (laserMode ? 62 : 36)) + Math.random() * (coreMode ? 125 : 74);
      const life = (coreMode ? .24 : .14) + Math.random() * (coreMode ? .30 : .20);
      state.particles.push({type:'spark',x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life,max:life,size:(coreMode?2.4:1.7)+Math.random()*(coreMode?3.6:2.2),crystalFx:true});
    }
    if (!laserMode) {
      const dustCount = coreMode ? 9 : (missileMode ? 6 : 4);
      for (let i = 0; i < dustCount; i++) {
        const life = (coreMode ? .30 : .18) + Math.random() * (coreMode ? .24 : .18);
        state.particles.push({type:'smoke',x:x+(Math.random()-.5)*10,y:y+(Math.random()-.5)*10,vx:(Math.random()-.5)*(coreMode?28:18),vy:(Math.random()-.5)*(coreMode?28:18),life,max:life,size:(coreMode?5.6:3.8)+Math.random()*(coreMode?4.8:2.8),crystalDust:true});
      }
    }
    destroySplashBricks(x, y, splashRadius);
    const splashRadius2 = splashRadius * splashRadius;
    const targets = getAllPlayerTanks().filter(t => t && t.alive && t !== excludedTank);
    for (const target of targets) {
      const slot = target.playerSlot || 1;
      const canHit = sourceTeam !== 'player' || (isPvpMode() && sourceSlot && sourceSlot !== slot);
      if (!canHit) continue;
      const cx = target.x + target.w / 2;
      const cy = target.y + target.h / 2;
      const dx = cx - x;
      const dy = cy - y;
      if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
    }
    if (sourceTeam === 'player') {
      for (const target of state.enemies || []) {
        if (!target?.alive || target === excludedTank) continue;
        const cx = target.x + target.w / 2;
        const cy = target.y + target.h / 2;
        const dx = cx - x;
        const dy = cy - y;
        if (dx * dx + dy * dy <= splashRadius2) damageTank(target, sourceTeam, sourceSlot, splashDamage, bypassInvuln);
      }
    }
    state.shake = Math.max(state.shake, coreMode ? 7.2 : (laserMode ? 4.2 : 4.8));
  }

  function addWormMushroom(x,y,radius=96){
    const r=Math.max(72,Number(radius)||96);
    state.particles.push({type:'blastRing',x,y,vx:0,vy:0,life:.72,max:.72,size:14,maxSize:r+28,thickness:20,wormFx:true});
    state.particles.push({type:'scorch',x,y,vx:0,vy:0,life:3.0,max:3.0,size:r*.40,wormFx:true});
    // Ствол грибовидного облака.
    for(let i=0;i<10;i++){
      const life=.75+Math.random()*.55;
      state.particles.push({type:'smoke',x:x+(Math.random()-.5)*12,y:y-i*7,vx:(Math.random()-.5)*16,vy:-24-Math.random()*18,life,max:life,size:8+i*.55+Math.random()*4,wormFx:true,wormCloud:true});
    }
    // Шапка гриба.
    for(let i=0;i<18;i++){
      const a=Math.random()*Math.PI*2, rr=8+Math.random()*30, life=.7+Math.random()*.6;
      state.particles.push({type:'smoke',x:x+Math.cos(a)*rr,y:y-68+Math.sin(a)*rr*.42,vx:Math.cos(a)*(18+Math.random()*30),vy:-12+Math.sin(a)*12,life,max:life,size:10+Math.random()*7,wormFx:true,wormCloud:true});
    }
    // Бело-фиолетовые осколки/искры.
    for(let i=0;i<28;i++){
      const a=Math.random()*Math.PI*2,s=75+Math.random()*190,life=.3+Math.random()*.5;
      state.particles.push({type:'spark',x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-24,life,max:life,size:2+Math.random()*4,wormFx:true});
    }
    state.shake=Math.max(state.shake,12);
  }

