    if(!target)return;const cx=p.x+p.w/2,cy=p.y+p.h/2,base=Math.atan2(target.y+target.h/2-cy,target.x+target.w/2-cx);
    for(let i=-5;i<=5;i++){const angle=base+i*.095,offset=Math.abs(i)*1.8;state.bullets.push({x:cx+Math.cos(angle)*(42+offset)-9,y:cy+Math.sin(angle)*(42+offset)-9,w:18,h:18,vx:Math.cos(angle)*275,vy:Math.sin(angle)*275,team:'player',alive:true,ownerSlot,kind:'sandWave',damage:1,waveSegment:true,trailTimer:0});}
    for(let i=0;i<18;i++){const a=base+(Math.random()-.5)*1.05,sp=70+Math.random()*120,max=.25+Math.random()*.3;state.particles.push({type:'smoke',x:cx+Math.cos(base)*35,y:cy+Math.sin(base)*35,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-5,life:max,max,size:4+Math.random()*4,sandWaveDust:true});}
