    state.bullets.push({x:cx+d.x*34-size/2,y:cy+d.y*34-size/2,w:size,h:size,vx:d.x*570,vy:d.y*570,team:'player',alive:true,ownerSlot:owner,kind:'mirageLance',damage:4,hp:4,lifeTime:2.5,ignoreTerrain:true,mirageLance:true,trailTimer:0});
