    for(let r=0;r<3;r++)state.particles.push({type:'shockwave',x:cx,y:cy,vx:0,vy:0,life:.55+r*.08,max:.55+r*.08,size:10+r*8,maxSize:radius*(.9+r*.12),thickness:15-r*3,mirageFx:true});
    for(let i=0;i<40;i++){const a=Math.random()*Math.PI*2,s=55+Math.random()*120,life=.22+Math.random()*.35;state.particles.push({type:'spark',x:cx,y:cy,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,size:1.4+Math.random()*2.7,mirageFx:true});}state.shake=Math.max(state.shake,6);
