  function zeroMarkImpact(x,y){state.particles.push({type:'shockwave',x,y,vx:0,vy:0,life:.36,max:.36,size:8,maxSize:54,thickness:9,voidFx:true});for(let i=0;i<14;i++){const a=Math.random()*Math.PI*2,s=40+Math.random()*100,life=.16+Math.random()*.18;state.particles.push({type:'spark',x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,size:1.5+Math.random()*2.4,voidFx:true});}}
