  function updateResearchVehicleSystems(p,dt){
    if(!p?.alive)return;if(Number(p.citadelDeployLock||0)>0)p.citadelDeployLock=Math.max(0,Number(p.citadelDeployLock||0)-dt);
    if(p.playerType==='mirage')emitMirageHoverFx(p,dt);
    else if(p.playerType==='hive')updateHiveSystems(p,dt);
    else if(p.playerType==='chronos')updateChronosSystems(p,dt);
    else if(p.playerType==='singularity')updateSingularitySystems(p,dt);
    else if(p.playerType==='prism')updatePrismSystems(p,dt);
    else if(p.playerType==='chimera')updateChimeraSystems(p,dt);
    else if(p.playerType==='zeroColossus')updateZeroSystems(p,dt);
  }
  function tryHitHiveDroneWithBullet(b){
    if(!b?.alive)return false;for(const p of getAllPlayerTanks()){if(!p?.alive||p.playerType!=='hive')continue;const slot=normalizePlayerSlot(p.playerSlot||1),hostile=b.team==='enemy'||(isPvpMode()&&b.team==='player'&&b.ownerSlot&&normalizePlayerSlot(b.ownerSlot)!==slot);if(!hostile)continue;const drones=ensureHiveDrones(p);for(let i=0;i<drones.length;i++){const d=drones[i];if(!d.alive)continue;const pos=hiveDroneWorldPos(p,d,i),bx=b.x+b.w/2,by=b.y+b.h/2,dist=Math.hypot(bx-pos.x,by-pos.y);if(Number(p.hiveInterceptTimer||0)>0&&dist<44){b.alive=false;for(let k=0;k<6;k++){const a=Math.random()*Math.PI*2,life=.12+Math.random()*.12;state.particles.push({type:'spark',x:pos.x,y:pos.y,vx:Math.cos(a)*(35+Math.random()*55),vy:Math.sin(a)*(35+Math.random()*55),life,max:life,size:1.2+Math.random()*1.8,hiveFx:true});}return true;}if(dist<13+Math.max(b.w,b.h)*.4){d.alive=false;d.hp=0;d.rebuild=12;b.alive=false;addExplosion(pos.x,pos.y,.45);return true;}}}return false;
  }
  function usePlayerBossAbility(p,slot){
    if(!p?.alive||(!PLAYER_BOSS_SOURCE[p.playerType]&&!LEMAN_RUSS_AUX_TYPES.has(p.playerType)&&p.playerType!=='baneblade'&&!RESEARCH_PLAYER_TYPES.has(p.playerType)))return;
    p.abilityCd=p.abilityCd||{q:0,e:0,g:0};const key=slot.toLowerCase();if((p.abilityCd[key]||0)>0)return;
    if(p.playerType==='baneblade'){const target=nearestEnemyToPlayer(p);if(key==='q'){fireBanebladeHullSiegeShell(p);p.abilityCd.q=7.8;}else if(key==='e'){startBanebladeBroadside(p,target);p.abilityCd.e=10.0;}else if(key==='g'){spawnBanebladeStubberBurst(p);p.abilityCd.g=4.8;}return;}
    if(p.playerType==='mirage'){if(key==='q'){miragePhaseDash(p);p.abilityCd.q=4.5;}else if(key==='e'){fireMiragePhaseLance(p);p.abilityCd.e=5.5;}else if(key==='g'){mirageGravityBurst(p);p.abilityCd.g=8.5;}return;}
    if(p.playerType==='researchCitadel'){if(key==='q'){toggleResearchCitadel(p);p.abilityCd.q=1.25;}else if(key==='e'){if(fireCitadelSiegeVolley(p))p.abilityCd.e=8.5;}else if(key==='g'){if(citadelAnchorPulse(p))p.abilityCd.g=9.5;}return;}
    if(p.playerType==='hive'){if(key==='q'){p.hiveFocusTimer=5;p.abilityCd.q=9;}else if(key==='e'){p.hiveInterceptTimer=4;p.abilityCd.e=13;}else if(key==='g'){if(hiveSwarmMissiles(p))p.abilityCd.g=8;}return;}
    if(p.playerType==='chronos'){if(key==='q'){chronosRewind(p);p.abilityCd.q=8.5;}else if(key==='e'){fireChronosBurst(p);p.abilityCd.e=6.5;}else if(key==='g'){p.chronosFieldTimer=4.5;p.chronosFieldTick=0;state.particles.push({type:'shockwave',x:p.x+p.w/2,y:p.y+p.h/2,vx:0,vy:0,life:.46,max:.46,size:18,maxSize:96,thickness:10,plasmaFx:true});p.abilityCd.g=10.5;}return;}
    if(p.playerType==='singularity'){if(key==='q'){if(deploySingularityWell(p))p.abilityCd.q=10.5;}else if(key==='e'){p.singularityShieldTimer=4.0;state.particles.push({type:'shockwave',x:p.x+p.w/2,y:p.y+p.h/2,vx:0,vy:0,life:.40,max:.40,size:18,maxSize:76,thickness:9,voidFx:true});p.abilityCd.e=13.0;}else if(key==='g'){if(launchSingularityNova(p))p.abilityCd.g=12.5;}return;}
    if(p.playerType==='prism'){if(key==='q'){p.prismMirrorTimer=5.0;state.particles.push({type:'shockwave',x:p.x+p.w/2,y:p.y+p.h/2,vx:0,vy:0,life:.46,max:.46,size:16,maxSize:84,thickness:10,plasmaFx:true});p.abilityCd.q=9.0;}else if(key==='e'){if(firePrismLance(p))p.abilityCd.e=7.5;}else if(key==='g'){if(startPrismWhiteStar(p))p.abilityCd.g=12.0;}return;}
    if(p.playerType==='chimera'){if(key==='q'){if(cycleChimeraMode(p))p.abilityCd.q=.85;}else if(key==='e'){if(activateChimeraArmor(p))p.abilityCd.e=11.0;}else if(key==='g'){if(fireChimeraTriune(p))p.abilityCd.g=13.0;}return;}
    if(p.playerType==='zeroColossus'){if(key==='q'){if(fireZeroErase(p))p.abilityCd.q=7.5;}else if(key==='e'){if(activateZeroArmor(p))p.abilityCd.e=13.5;}else if(key==='g'){if(startZeroAnnihilation(p))p.abilityCd.g=15.0;}return;}

    if(LEMAN_RUSS_AUX_TYPES.has(p.playerType)){
      if(key==='g'){spawnLemanRussAuxVolley(p);p.abilityCd.g=6.5;}
      return;
    }
    const src=PLAYER_BOSS_SOURCE[p.playerType],target=nearestEnemyToPlayer(p),cx=p.x+p.w/2,cy=p.y+p.h/2,owner=normalizePlayerSlot(p.playerSlot||1);
    if(!target && (key==='e'||key==='g'))return;
    if(src==='boss'){
      const base=target?Math.atan2(target.y+target.h/2-cy,target.x+target.w/2-cx):0;
      if(key==='q'){for(let i=0;i<16;i++)spawnPlayerBossBullet(cx,cy,Math.PI*2*i/16,220,9,'radial',owner);p.abilityCd.q=5;}
      else if(key==='e'){for(let i=-3;i<=3;i++)spawnPlayerBossBullet(cx,cy,base+i*.14,290,8,'fan',owner);p.abilityCd.e=5;}
      else if(key==='g'){for(const a of [0,Math.PI/2,Math.PI,Math.PI*1.5,Math.PI/4,Math.PI*.75,Math.PI*1.25,Math.PI*1.75])spawnPlayerBossBullet(cx,cy,a,260,10,'cross',owner);p.abilityCd.g=5;}addExplosion(cx,cy,.8);
    }else if(src==='sonicBoss'){
      const base=Math.atan2(target.y+target.h/2-cy,target.x+target.w/2-cx);
      if(key==='q'){for(let i=-2;i<=2;i++)spawnPlayerSonicWave(cx,cy,base+i*.19,250,20,owner);p.abilityCd.q=5;}
      else if(key==='e'){for(let i=0;i<8;i++)spawnPlayerSonicWave(cx,cy,Math.PI*2*i/8,218,19,owner);p.abilityCd.e=5;}
      else if(key==='g'){for(const a of [base,base+Math.PI/2,base-Math.PI/2])spawnPlayerSonicWave(cx,cy,a,275,21,owner);p.abilityCd.g=5;}addExplosion(cx,cy,.7);
    }else if(src==='rocketBoss'){
      if(key==='q'){playerRocketRadial(p,owner);p.abilityCd.q=5;}
      else if(key==='e'){schedulePlayerRocketAirstrike(target,owner);p.abilityCd.e=7;}
      else if(key==='g'){shoot(p);p.abilityCd.g=3;}
    }else if(src==='leviathan'){
      if(key==='q'){playerLeviathanShockwave(p,owner);p.abilityCd.q=6;}
      else if(key==='e'){playerLeviathanMissileAttack(p,target,owner);p.abilityCd.e=7;}
      else if(key==='g'){startPlayerLeviathanLaser(p,target);p.abilityCd.g=9;}
    }else if(src==='sandTitan'){
      if(key==='q'){playerSandAirstrikeBurst(p,target,owner);p.abilityCd.q=7;}
      else if(key==='e'){playerSandArcWave(p,target,owner);p.abilityCd.e=6;}
      else if(key==='g'){startPlayerSandLaser(p,target);p.abilityCd.g=10;}
    }else if(src==='citadelBoss'){
      if(key==='q'){playerBastionRadial(p,owner);applyBastionSharedSpecialCooldown(p);}
      else if(key==='e'){schedulePlayerBastionBombardment(p,target,owner);applyBastionSharedSpecialCooldown(p);}
      else if(key==='g'){playerBastionSiegebreaker(p,target,owner);applyBastionSharedSpecialCooldown(p);}
    }
  }
  function updatePlayerBossCooldowns(p,dt){
    if(!p)return;
    if(p.abilityCd)for(const k of ['q','e','g'])p.abilityCd[k]=Math.max(0,(p.abilityCd[k]||0)-dt);
    updateBanebladeSystems(p,dt);
    updateResearchVehicleSystems(p,dt);
    if(Number(p.lemanAuxFlash||0)>0)p.lemanAuxFlash=Math.max(0,Number(p.lemanAuxFlash||0)-dt);
    if(Number(p.plasmaAuxFlash||0)>0)p.plasmaAuxFlash=Math.max(0,Number(p.plasmaAuxFlash||0)-dt);
    if(Number(p.hyperionAuxFlash||0)>0)p.hyperionAuxFlash=Math.max(0,Number(p.hyperionAuxFlash||0)-dt);
    if(Number(p.hyperionChargeFxTimer||0)>0)p.hyperionChargeFxTimer=Math.max(0,Number(p.hyperionChargeFxTimer||0)-dt);
    if(p.playerType==='lemanRussHyperion' && Number(p.fireCooldown||0)>0){
      p.hyperionChargeFxTimer=Number(p.hyperionChargeFxTimer||0)-dt;
      if(p.hyperionChargeFxTimer<=0){
        p.hyperionChargeFxTimer=.055;
        const d=DIRS[p.dir]||DIRS.right,cx=p.x+p.w/2,cy=p.y+p.h/2,mx=cx+d.x*22,my=cy+d.y*22;
        const max=.14+Math.random()*.14;
        state.particles.push({type:'spark',x:mx+(Math.random()-.5)*4,y:my+(Math.random()-.5)*4,vx:(Math.random()-.5)*30+d.x*(8+Math.random()*12),vy:(Math.random()-.5)*30+d.y*(8+Math.random()*12),life:max,max,size:1.5+Math.random()*1.8,plasmaFx:true});
      }
    }
    if(p.playerType==='playerBastion'){
      if(Number(p.citadelCoreFlash||0)>0)p.citadelCoreFlash=Math.max(0,Number(p.citadelCoreFlash||0)-dt);
      const phase=getBossCurrentPhase(p);
      p.damageFxTimer=Number(p.damageFxTimer||.24)-dt;
      if(phase>=2&&p.damageFxTimer<=0){
        const smokeCount=phase>=4?3:2;
        for(let i=0;i<smokeCount;i++){
          const max=.75+Math.random()*.35;
          const px=p.x+p.w*(.18+Math.random()*.64),py=p.y+p.h*(.16+Math.random()*.68);
          state.particles.push({type:'smoke',x:px,y:py,vx:(Math.random()-.5)*24,vy:-18-Math.random()*24,life:max,max,size:5.5+Math.random()*3.5});
        }
        if(Math.random()<(phase>=4?.55:.28)){
          const sx=p.x+p.w*(.22+Math.random()*.56),sy=p.y+p.h*(.22+Math.random()*.56);
          for(let i=0;i<(phase>=4?3:1);i++){
            const a=Math.random()*Math.PI*2,s=55+Math.random()*75,max=.18+Math.random()*.2;
            state.particles.push({type:'spark',x:sx,y:sy,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:max,max,size:1.7+Math.random()*2.8});
          }
        }
        p.damageFxTimer=phase>=4?.14:.26;
      }
    }
    updatePlayerBossLasers(p,dt);
  }

  function localInputState() {
    return {
      up: keys.has('ArrowUp') || keys.has('KeyW'),
      down: keys.has('ArrowDown') || keys.has('KeyS'),
      left: keys.has('ArrowLeft') || keys.has('KeyA'),
      right: keys.has('ArrowRight') || keys.has('KeyD'),
      shoot: keys.has('Space'), q:keys.has('KeyQ'), e:keys.has('KeyE'), g:keys.has('KeyG')
    };
  }

  function inputStateSignature(input) {
    return `${input.up?1:0}${input.down?1:0}${input.left?1:0}${input.right?1:0}${input.shoot?1:0}${input.q?1:0}${input.e?1:0}${input.g?1:0}`;
  }

  function updatePlayerWithInput(p, input, dt) {
    if (!p || !p.alive) return;
    if (Number(p.stunTimer||0) > 0) {
      p.iceVx=0;p.iceVy=0;
      updatePlayerBossCooldowns(p,dt);
      p._qHeld=!!input.q;p._eHeld=!!input.e;p._gHeld=!!input.g;
      return;
    }
    if(p.playerType==='sputnik'){
      const activeSputnik=getActiveSputnikMissile(normalizePlayerSlot(p.playerSlot||1));
      if(activeSputnik){
        steerSputnikMissile(activeSputnik,input,dt);
        p.iceVx=0;p.iceVy=0;
        updatePlayerBossCooldowns(p,dt);
        p._qHeld=!!input.q;p._eHeld=!!input.e;p._gHeld=!!input.g;
        return;
      }
    }
    if(p.playerType==='playerSandWorm'){
      p.spiceFxTimer=Number(p.spiceFxTimer||0)-dt;
      if(p.spiceFxTimer<=0){
        const d=DIRS[p.dir]||DIRS.down;
        const ang=d.angle||0,ca=Math.cos(ang),sa=Math.sin(ang);
        const cx=p.x+p.w/2,cy=p.y+p.h/2;
        // Буквально те же четыре кормовые точки и те же частицы, что у оригинального босса.
        for(const ly of [-24,-8,8,24]){
          const lx=-64;
          const px=cx+ca*lx-sa*ly,py=cy+sa*lx+ca*ly;
          const max=.8+Math.random()*.65;
          const backX=-ca,backY=-sa;
          state.particles.push({type:'smoke',x:px,y:py,vx:backX*(16+Math.random()*24)+(Math.random()-.5)*10,vy:backY*(16+Math.random()*24)-12-Math.random()*12,life:max,max,size:6+Math.random()*5,spiceSmoke:true});
          if(Math.random()<.35){
            const sm=.25+Math.random()*.25;
            state.particles.push({type:'spark',x:px,y:py,vx:backX*(20+Math.random()*28)+(Math.random()-.5)*22,vy:backY*(20+Math.random()*28)-8,life:sm,max:sm,size:1.3+Math.random()*2,spiceSpark:true});
          }
        }
        p.spiceFxTimer=.14;
      }
    }

    let dir = null;
    if (input.up) dir = 'up';
    else if (input.down) dir = 'down';
    else if (input.left) dir = 'left';
    else if (input.right) dir = 'right';

    if(p.playerType==='researchCitadel'&&p.citadelDeployed){p.iceVx=0;p.iceVy=0;if(dir)p.dir=dir;if(input.shoot)shoot(p);updatePlayerBossCooldowns(p,dt);if(input.q&&!p._qHeld)usePlayerBossAbility(p,'q');if(input.e&&!p._eHeld)usePlayerBossAbility(p,'e');if(input.g&&!p._gHeld)usePlayerBossAbility(p,'g');p._qHeld=!!input.q;p._eHeld=!!input.e;p._gHeld=!!input.g;return;}
    const onIce = p.playerType!=='mirage' && isSlipperyCell(tankCenterCell(p));
    p.iceVx = Number.isFinite(p.iceVx) ? p.iceVx : 0;
    p.iceVy = Number.isFinite(p.iceVy) ? p.iceVy : 0;

    if (onIce) {
      // На льду и нефтяной жиже сохраняется инерция, а смена направления происходит заметно медленнее.
      if (dir) {
        p.dir = dir;
        const d = DIRS[dir];
        const targetSpeed = p.speed * .94 * terrainSpeedMultiplier(p);
        const steering = 1 - Math.exp(-1.65 * dt);
        p.iceVx += (d.x * targetSpeed - p.iceVx) * steering;
        p.iceVy += (d.y * targetSpeed - p.iceVy) * steering;
      } else {
        const glide = Math.pow(.985, dt * 60);
        p.iceVx *= glide;
        p.iceVy *= glide;
      }
      if (!tryMove(p, p.iceVx * dt, p.iceVy * dt)) {
        p.iceVx *= .25;
        p.iceVy *= .25;
      }
    } else if (dir) {
      p.dir = dir;
      assistLaneAlignment(p, dir, dt);
      const d = DIRS[dir];
      const terrainMul = terrainSpeedMultiplier(p);
      tryMove(p, d.x * p.speed * terrainMul * dt, d.y * p.speed * terrainMul * dt);
      p.iceVx = d.x * p.speed * terrainMul;
      p.iceVy = d.y * p.speed * terrainMul;
    } else {
      p.iceVx = 0;
      p.iceVy = 0;
    }
    emitLemanRussSmokeTrail(p,dt);
    if(input.shoot)shoot(p); updatePlayerBossCooldowns(p,dt); if(input.q&&!p._qHeld)usePlayerBossAbility(p,'q'); if(input.e&&!p._eHeld)usePlayerBossAbility(p,'e'); if(input.g&&!p._gHeld)usePlayerBossAbility(p,'g'); p._qHeld=!!input.q;p._eHeld=!!input.e;p._gHeld=!!input.g;
  }

  function playerUpdate(dt) {
    updatePlayerWithInput(state.player, localInputState(), dt);
    if (networkMode === 'lan' && networkIsHost) {
      updatePlayerWithInput(state.ally, networkRemoteInput, dt);
      updatePlayerWithInput(state.ally2, networkRemoteInput3, dt);
    }
  }


  function lineOfSight(a, b, dir) {
    const acx = a.x+a.w/2, acy = a.y+a.h/2;
    const bcx = b.x+b.w/2, bcy = b.y+b.h/2;
    if ((dir === 'up' || dir === 'down') && Math.abs(acx-bcx) < 20) {
      if (dir === 'up' && bcy >= acy) return false;
      if (dir === 'down' && bcy <= acy) return false;
      return true;
    }
    if ((dir === 'left' || dir === 'right') && Math.abs(acy-bcy) < 20) {
      if (dir === 'left' && bcx >= acx) return false;
      if (dir === 'right' && bcx <= acx) return false;
      return true;
    }
    return false;
  }

  function spawnEnemyBullet(cx, cy, angle, speed = 255, size = 8, kind = 'special') {
    state.bullets.push({x:cx-size/2,y:cy-size/2,w:size,h:size,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,team:'enemy',alive:true,kind});
  }

  function spawnSonicWave(cx, cy, angle, speed = 245, size = 20) {
    state.bullets.push({x:cx-size/2,y:cy-size/2,w:size,h:size,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,team:'enemy',alive:true,kind:'sonicWave',brickPierce:2});
  }

  function sonicBossSpecialAttack(t, target) {
    const cx=t.x+t.w/2, cy=t.y+t.h/2;
    const phase=t.specialIndex++%3;
    const base=Math.atan2(target.y+target.h/2-cy,target.x+target.w/2-cx);
    if (phase===0) {
      for(let i=-2;i<=2;i++) spawnSonicWave(cx,cy,base+i*.19,250,20);
    } else if (phase===1) {
      for(let i=0;i<8;i++) spawnSonicWave(cx,cy,(Math.PI*2*i)/8,218,19);
    } else {
      for(const a of [base,base+Math.PI/2,base-Math.PI/2]) spawnSonicWave(cx,cy,a,275,21);
    }
    addExplosion(cx,cy,.7);
  }

  function bossSpecialAttack(t, target) {
    const cx=t.x+t.w/2, cy=t.y+t.h/2;
    const phase=t.specialIndex++%3;
    if (phase===0) {
      for(let i=0;i<16;i++) spawnEnemyBullet(cx,cy,(Math.PI*2*i)/16,220,9,'radial');
    } else if (phase===1) {
      const base=Math.atan2(target.y+target.h/2-cy,target.x+target.w/2-cx);
      for(let i=-3;i<=3;i++) spawnEnemyBullet(cx,cy,base+i*.14,290,8,'fan');
    } else {
      for(const a of [0,Math.PI/2,Math.PI,Math.PI*1.5,Math.PI/4,Math.PI*.75,Math.PI*1.25,Math.PI*1.75]) spawnEnemyBullet(cx,cy,a,260,10,'cross');
    }
    addExplosion(cx,cy,.8);
  }

  function spawnRocketBossRadial(t) {
    const cx=t.x+t.w/2, cy=t.y+t.h/2;
    const count = 12;
    const angleOffset = Math.random() * Math.PI * 2;
    for (let i=0; i<count; i++) {
      const angle = angleOffset + Math.PI * 2 * i / count;
      const size = 11;
      state.bullets.push({
        x:cx-size/2, y:cy-size/2, w:size, h:size,
        vx:Math.cos(angle)*198, vy:Math.sin(angle)*198,
        team:'enemy', alive:true, kind:'rocketMissile', damage:1,
        splashRadius:48, splashDamage:1, trailTimer:0, bossRocket:true
      });
    }
    addExplosion(cx,cy,.9);
  }

  function scheduleRocketAirstrike(target) {
    if (!target || !target.alive) return;
    if (!state.airstrikes) state.airstrikes=[];
    const tcx=target.x+target.w/2, tcy=target.y+target.h/2;
    const angle=Math.random()*Math.PI*2;
    const offset=42+Math.random()*92;
    const radius=96;
    state.airstrikes.push({
      x:clamp(tcx+Math.cos(angle)*offset,radius+8,W-radius-8),
      y:clamp(tcy+Math.sin(angle)*offset,radius+8,H-radius-8),
      radius, damage:1, life:2.2, max:2.2, seed:Math.random()*1000, impacted:false
    });
  }

  function rocketBossSpecialAttack(t, target) {
    const phase=t.specialIndex++%2;
    if (phase===0) spawnRocketBossRadial(t); // Только полный круг, без веерной/дуговой атаки.
    else scheduleRocketAirstrike(target);
  }

  function spawnCitadelRadialBarrage(t, team=t?.team||'enemy', ownerSlot=0) {
    const cx=t.x+t.w/2, cy=t.y+t.h/2;
    const phase=getBossCurrentPhase(t);
    const count=phase>=3?18:14;
    const angleOffset=Math.random()*Math.PI*2;
    for(let i=0;i<count;i++){
      const angle=angleOffset+Math.PI*2*i/count;
      const size=12;
      state.bullets.push({
        x:cx-size/2,y:cy-size/2,w:size,h:size,
        vx:Math.cos(angle)*(phase>=4?232:212),vy:Math.sin(angle)*(phase>=4?232:212),
        team,alive:true,ownerSlot:team==='player'?ownerSlot:0,kind:'rocketMissile',damage:1,
        splashRadius:phase>=4?42:34,splashDamage:1,trailTimer:0,bossRocket:true,citadelRocket:true
      });
    }
    addExplosion(cx,cy,.9);
  }

