      ctx.fillStyle='rgba(120,170,255,.11)';
      for(let i=0;i<42;i++){const px=W*.54+((i*97+43)%(W*.40)),py=(i*61+17)%H;ctx.fillRect(px,py,2+(i%2),2+(i%2));}

