      ctx.fillStyle='rgba(196,255,110,.020)';
      for(let i=0;i<7;i++){ const px=70+i*104, py=56+(i%3)*130; ctx.beginPath(); ctx.ellipse(px,py,30+Math.sin(tt+i)*4,10+Math.cos(tt*1.2+i)*2,.1,0,Math.PI*2); ctx.fill(); }
