    if(charge>0){const progress=1-charge/2,pulse=.25+.2*Math.sin(performance.now()*.03);ctx.strokeStyle=`rgba(156,84,255,${.22+progress*.30})`;ctx.lineWidth=1.5+pulse;ctx.setLineDash([7,7]);ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(endX,endY);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=`rgba(218,190,255,${.38+progress*.52})`;ctx.beginPath();ctx.arc(start.x,start.y,6+progress*7,0,Math.PI*2);ctx.fill();}
    else{ctx.strokeStyle='rgba(61,18,92,.34)';ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(endX,endY);ctx.stroke();ctx.strokeStyle='rgba(151,63,232,.90)';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(endX,endY);ctx.stroke();ctx.strokeStyle='#f2dcff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(endX,endY);ctx.stroke();}
