          ctx.fillStyle=`rgba(255,253,238,${.78+.18*pulse})`;ctx.beginPath();ctx.moveTo(20.5,0);ctx.lineTo(11.8,-2.2);ctx.lineTo(13.2,0);ctx.lineTo(11.8,2.2);ctx.closePath();ctx.fill();
